"explanation": "ロココ様式は18世紀前半にフランスで発展した様式で、バロック様式の重厚さへの反動として生まれた。貝殻・草花・唐草などの繊細な曲線装飾、淡いパステルカラー、軽快で優雅な雰囲気が特徴。\n\nA：バロック様式の特徴は直線ではなく、動感のある曲線と豊かな装飾が特徴である。\nC：ゴシック様式（12〜15世紀）はロマネスク様式（10〜12世紀）の後に成立した。また、ゴシックの特徴は尖頭アーチとステンドグラスの大窓であり、小窓はロマネスクの特徴。\nD：ルネサンス様式はゴシックの後に生まれたことは正しいが、左右非対称の有機的装飾はアール・ヌーヴォーの特徴。ルネサンスは左右対称・均整美・古典主義的秩序を特徴とする。\n\n【頻出】様式の時系列：ロマネスク→ゴシック→ルネサンス→バロック→ロココ→新古典主義→アール・ヌーヴォー→アール・デコの順は必須知識。\n【混同注意】バロックとロココは混同されやすい。バロック＝重厚・動感・宗教的、ロココ＝軽快・優美・世俗的と対比して覚える。"

