"explanation": "一般的な住宅における廊下の有効幅は780mm（約800mm）以上が推奨寸法とされており、車椅子使用者が自力で走行するには850mm〜900mm以上が必要とされている。\n\nA：建築基準法では廊下幅の規定は用途・規模により異なり、「75cm以上」という車椅子通行の法定基準は存在しない。バリアフリー法では整備基準として有効幅120cm以上（推奨150cm以上）を求めており、75cmは不足。\nC：建築基準法施行令第23条では、住宅の階段の蹴上げは23cm以下（正しい）、踏面は15cm以上（正しい）が規定されている。この選択肢は正しい内容のように見えるが、踏面15cm以上という規定は狭すぎる印象を与えるひっかけで、数値自体は正しい。ただし本問の正解は選択肢Bであるため相対的に誤答となる。\nD：逆。人が横向きで通過できる最小寸法は約450mm、正面向きでの通過最小寸法は約600mmとされる。\n\n【頻出】廊下有効幅の目安：一般人600mm、荷物持ち750mm、車椅子自走850〜900mm、車椅子介助1200mmの系列は頻出。\n【混同注意】建築基準法の最低基準と推奨寸法・バリアフリー法の基準は別物。混同しないよう出典を意識して覚える。"

