"explanation": "木造軸組工法（在来工法）は柱・梁・胴差などの軸材（線材）を組み合わせ、筋交い・耐力壁を加えた骨組みで建物の鉛直荷重と地震・風などの水平荷重に抵抗する。日本古来の伝統的な木造構法を発展させたもの。\n\nB：木造枠組壁工法（2×4工法）は木造軸組工法とは別の構法。枠組壁工法は壁・床・屋根のパネル（面材）で荷重を支える「面構造」であり、軸材主体の軸組工法とは根本的に異なる。\nC：耐力壁は建物の縦・横（X方向・Y方向）の両方向に均等に配置することが構造安全上の基本原則であり、一方向集中は誤り。\nD：木造軸組工法は軸材（柱・梁）が主体のため、壁面に比較的自由に開口部を設けやすいことが特徴のひとつ。大開口も設計上可能（構造計算が必要）。\n\n【頻出】木造軸組工法と枠組壁工法（2×4）の比較は頻出。軸組＝線（柱・梁）が主体・開口自由、枠組壁＝面（パネル）が主体・開口制限あり、と対比して覚える。\n【混同注意】耐力壁はX・Y両方向にバランスよく配置する必要がある点は構造計画の基本。"

