"バリアフリー法（高齢者・障害者等の移動等の円滑化の促進に関する法律）では、特定施設の出入口有効幅は80cm以上が基準とされる",

"段差解消のためのスロープ勾配は、バリアフリー法の整備基準において1/12以下（推奨は1/15以下）とされる",

"住宅内の手すりは廊下・トイレ・浴室・階段に設けることが高齢者向け住宅では一般的で、廊下手すりの取り付け高さは床面から75〜85cmが目安とされる",

