"explanation": "マゼンタはCMYK（シアン・マゼンタ・イエロー・キー/ブラック）の基本色のひとつとして正しいが、「青みがかった暗い紫色」という説明が誤り。マゼンタは赤みがかった鮮やかな明るいピンク〜赤紫系の色で、印刷の三原色では赤の役割を担う。1859年のマジェンタの戦いに由来するとも言われる。\n\nA：正しい。鶯色は日本の伝統色で、黄緑がかった暗い緑色。ウグイスの羽の色に由来するが、実際のウグイスは茶褐色に近く、日本人がイメージする春の色として定着した。\nB：正しい。コバルトブルーはCoAl₂O₄の顔料に由来する鮮やかな中明度の青色。19世紀以降、絵具・陶磁器の釉薬として広く使われてきた。\nC：正しい。エクルーはフランス語ecruから来る色名で、未漂白素材の自然なクリームベージュ色。インテリアのファブリック色名として頻繁に使われる。\n\n【頻出】インテリアで頻出する色名：エクルー・オフホワイト・アイボリー・グレージュ（グレー×ベージュ）・テラコッタ・セージグリーン等の系統と語源を理解しておくこと。\n【混同注意】マゼンタ（赤みのある明るいピンク〜赤紫）とバイオレット（青みがかった紫）・パープル（赤みがかった紫）は全て異なる色。印刷3原色のマゼンタ≠暗い紫。"

