"explanation": "第3種換気（排気機械・給気自然）は建築基準法のシックハウス対策における機械換気設備として認められており、採用が禁止されているわけではない。住宅では低コストで設置できる第3種換気が広く採用されており、法令上は第1〜3種いずれも認められている。\n\nA：正しい。ホルムアルデヒド（HCHO）はVOCの代表的な物質で、合板・接着剤・壁紙などから揮発し、シックハウス症候群の主因のひとつ。\nB：正しい。建材のホルムアルデヒド発散等級はJIS・JASの規格区分で、F☆☆☆☆（4スター）が最低発散量で使用面積制限なし、F☆（1スター）は発散量が最も多く居室使用不可。\nC：正しい。クロルピリホスは強い毒性・神経毒性を持つ有機リン系化合物で、建築基準法施行令により居室を有する建築物への使用が全面禁止されている（2003年）。\n\n【頻出】シックハウス対策の法規制：ホルムアルデヒドのF☆区分、クロルピリホス全面禁止、換気回数0.5回/h以上の義務（2003年）はセットで覚える。\n【混同注意】F☆☆☆☆（4スター）が「最良」、F☆（1スター）が「最悪」という評価方向を逆に覚えないこと。星の数が多いほど安全・低発散。"

