"explanation": "ウレタンフォームはソファのクッション材として最も広く使用される素材。密度はkg/m³で表され、一般的に密度が高いほど重量があり耐圧縮性が高く、長期使用でのへたり（復元力の低下）が生じにくい。密度25kg/m³以上が中級、35kg/m³以上が高耐久の目安とされる。\n\nA：ウェービングテープ（ゴムバンド）張りはコイルスプリングより一般的に弾力性・耐久性が劣り、低〜中価格帯のソファに多く使われる。コイルスプリング（8の字スプリング・ポケットコイル等）の方が高級ソファに採用される傾向がある。\nB：カウチソファは座面の片側（または両側）に脚を伸ばせる延長部分（シェーズロング）を持つソファのこと。「複数連結したシステムソファの総称」はセクショナルソファの説明。\nD：セクショナルソファとは複数のパーツ（アームソファ・コーナーソファ・オットマン等）を組み合わせて構成するシステムソファ。「背もたれを持たないベンチ型」はオットマンまたはデイベッドの説明。\n\n【頻出】ソファの種類の名称と形状：1人掛け（アームチェア）・2人掛け・3人掛け・カウチ・セクショナル（組み合わせ）・ラブシート（2人掛け小型）の区別は頻出。\n【混同注意】カウチ（脚を伸ばせる一体型）とセクショナル（複数パーツ組み合わせ）は異なる。オットマン（脚置き）とカウチを混同しないこと。"

