"explanation": "コンクリートのひび割れには構造上無害な乾燥収縮によるものから、鉄筋腐食・中性化・アルカリ骨材反応などに起因する構造的に危険なものまで多様な種類がある。建築基準法では建物の安全性・耐久性に関する維持管理義務が定められており、危険なひび割れには補修が必要。「すべてのひび割れが無害で補修義務なし」とするのは誤り。\n\nA：正しい。コンクリートは圧縮力に強く引張力に弱い。鉄筋は引張力に強い。両者を組み合わせることで圧縮・引張・曲げに対応できる複合構造となる。\nB：正しい。壁式RC構造は耐力壁と床スラブで構成され、柱・梁の室内への出っ張りがなくすっきりした室内空間が得られる。中高層マンションに広く採用。\nC：正しい。ラーメン構造（柱・梁フレーム）は開口部の設置に自由度が高く、壁式構造より大きな窓や間仕切りの変更がしやすい。\n\n【頻出】RC造の壁式構造（壁・スラブが主体）とラーメン構造（柱・梁が主体）の比較、および開口自由度・間取り変更のしやすさの違いは頻出。\n【混同注意】「ラーメン」は食べ物ではなくドイツ語で「枠・骨組み」の意味。柱と梁を剛接合した構造形式を指す。"

