"explanation": "白熱電球（白熱灯）は太陽光に最も近い連続したスペクトルを持ち、演色評価数Raは100（最高値）。赤みがかった温かみのある電球色（色温度2700〜3000K）が特徴。発光効率は10〜15lm/Wと低く、LEDの100〜150lm/Wと比べて消費電力が大幅に大きい。\n\nB：高演色性蛍光灯（Ra90以上の高演色型）も存在し、美術館・医療施設等に使用実績がある。「蛍光灯は高演色用途に使用できない」は誤り。ただしLEDへの移行が進んでいる。\nC：LED照明の寿命は一般的に40000時間以上と長寿命が特徴であり、「寿命が短い」は誤り。初期コストが高い（白熱電球・蛍光灯より）ことも事実と逆。普及の主な理由は長寿命・省エネ・低ランニングコスト。\nD：電球色の色温度は2700〜3000K（暖色系）で、5000〜6500Kは昼白色〜昼光色の説明。「電球色が5000〜6500K」は全くの誤り。\n\n【頻出】光源の色温度分類：電球色2700〜3000K・温白色3500K・白色4000K・昼白色5000K・昼光色6500K前後の系列は頻出。\n【混同注意】電球色（低色温度・暖色・くつろぎ向き）と昼光色（高色温度・寒色・集中向き）を逆に覚えないこと。色温度の数値と用途の組み合わせを確実に暗記する。"

