"explanation": "ポストモダンデザインは、モダニズム（バウハウス以来の機能主義・「形態は機能に従う」）が支配的だった1950〜60年代への批判として1970〜80年代に登場。歴史様式（古典・バロック・ポップカルチャー等）の引用・折衷・装飾の復権・ユーモアやアイロニーを特徴とし、「少ないほど豊か」（ミース）への批判として「少ないほどつまらない」（ヴェンチューリ）が象徴的なスローガン。\n\nB：メンフィスは1981年にイタリアのミラノでエットーレ・ソットサスが中心となって結成されたデザイングループ。ドイツのデュッセルドルフは誤り。明るい色彩・幾何学的文様・遊び心あるフォルムでポストモダンを代表する。\nC：フィリップ・スタルクはフランスのデザイナーで、ユーモア・挑発性・有機的フォルムを持つ製品（レモン絞り「ジューシー・サリフ」等）で知られる。機能主義の徹底・装飾排除とは真逆のポストモダン的アプローチが特徴。\nD：ポストモダンは歴史様式の「引用・折衷」を積極的に活用することが特徴であり、歴史様式の引用を「禁じる」のはモダニズムの立場。定義が逆。\n\n【頻出】ポストモダンのキーパーソン：ロバート・ヴェンチューリ（理論的提唱者）・チャールズ・ムーア・マイケル・グレイブス（建築）・エットーレ・ソットサス（メンフィス）は頻出。\n【混同注意】モダニズム（機能主義・装飾排除）とポストモダニズム（装飾復権・歴史引用・折衷）の方向性は正反対。"

