"explanation": "方形屋根（ほうぎょう屋根）は四方向に傾斜しているが、「四方に棟（むね）を持つ」は誤り。方形屋根は頂点（一点）から四方向に傾斜が広がる形式で、水平方向の棟がなく頂点だけに集約される。棟が四方向にあるのは寄棟屋根（4枚の傾斜面＋水平棟が2本＋隅棟4本の構成）との混同。\n\nA：正しい。切妻屋根は2枚の傾斜面と1本の棟から構成される最もシンプルな形式。日本の木造住宅で最も多く使われる屋根形式で、構造・施工・コストの面で優れる。\nB：正しい。寄棟屋根は4枚の傾斜面を持ち、四方から雨を受け流せるため外壁への雨水飛散が少ない。和風・洋風を問わず安定した外観を呈する。\nC：正しい。陸屋根はRC造・鉄骨造のビル・マンションに多い。屋上利用（テラス等）も可能だが、雨水排水・防水層のメンテナンスが重要課題。\n\n【頻出】屋根の種類（切妻・寄棟・方形・入母屋・陸屋根・片流れ）の形状・棟の位置・特徴の比較は頻出。図で形状を覚えることが確実。\n【混同注意】方形屋根（頂点一点・棟なし）と寄棟屋根（棟あり・四方傾斜）は外観が似ているが棟の有無で区別する。"

