"explanation": "アンティークの定義として最も広く知られる基準は米国関税法（Tariff Act）で、「製造から100年以上経過した美術品・工芸品・家具」は関税免除対象とされている。インテリア・骨董業界でも100年以上を「アンティーク」とする用語が一般的に使われている。\n\nB：ヴィンテージはアンティークと同義ではない。一般にヴィンテージは製造後20〜99年程度の製品（時代感があり価値の高い中古品）を指し、アンティーク（100年以上）とは区別される。「国際統一定義」として同義とする規定は存在しない。\nC：アンティーク家具の修復（リストレーション）では、オリジナルの素材・塗装・形状をできる限り保存・再現することが原則。新品同様に見えるよう大幅に変えることは「修復」ではなく「リメイク・改造」にあたり、むしろアンティーク価値を損なう。\nD：チッペンデールはイギリスの家具職人トーマス・チッペンデールが18世紀（1750年代）に出版した家具デザイン書に由来するイギリスの家具様式。アメリカ人デザイナー・19世紀・鉄と大理石という説明はすべて誤り。木材（マホガニー等）を多用したロココ様式と中国趣味を融合させた精緻な木工が特徴。\n\n【頻出】アンティーク（100年以上）とヴィンテージ（20〜99年程度）の区分は家具・インテリアの市場で頻繁に使われる用語。試験でも出題される。\n【混同注意】チッペンデール（18世紀イギリス・木工・ロココ）とビクトリアン（19世紀イギリス・重厚装飾）・アーツ＆クラフツ（19世紀末・手工芸復興）は時代・様式が異なる。"

