"マンションの専有部分における床仕上げ材の変更は、管理規約で遮音等級の基準（LL-45またはLL-40以下等）が定められている場合があり、基準未満の材料への変更は制限される",

"マンションの専有部分内の工事はすべて管理組合の承認なく自由に行うことができ、施工前の届出・申請は任意とされている"

