"explanation": "マンションの専有部分内の工事であっても、ほとんどの管理規約では施工前に管理組合への届出・申請・承認が必要とされている。特に給排水配管の変更・床材変更（遮音基準の確認）・間仕切り変更等は管理組合の審査を経ることが一般的。「すべて自由・申請は任意」とするのは誤り。\n\nA：正しい。共用部分の変更は区分所有法第17条で管理組合の集会決議（特別決議の場合も）が必要。バルコニーは専用使用権を持つ共用部分であり、単独改修は原則不可。\nB：正しい。専有部分内であっても排水の縦管（共用配管）への接続・スラブへの穴あけは共用部分に影響するため、管理規約で制限されることが多い。\nC：正しい。フローリング等への床材変更時に遮音等級の基準を設けている管理規約は多く、LL-45・LL-40等の遮音性能を下回る材料の使用を禁止していることがある。\n\n【頻出】マンションリノベーションにおける専有部分と共用部分の区別、および管理規約による制限の範囲は頻出テーマ。区分所有法と管理規約の関係も理解しておくこと。\n【混同注意】「専有部分だから自由」という誤解が最も多い。専有部分内でも隣戸・共用設備に影響する工事は管理組合の承認が必要。"

