"answer": 3,

"explanation": "飲食店の厨房面積と客席面積の比率について、建築基準法や食品衛生法に一律に「30%以上」という法定比率の規定は存在しない。厨房の規模は業態・メニュー・客席数・提供方式によって異なり、設計上の目安として参考比率が示される場合はあるが、法律で一律に定められているという記述は誤り。建築確認申請の審査基準でもない。\n\nA：正しい。VMDは小売業・飲食業での空間商品演出の総合手法。フォーカルポイント（視覚的焦点）・ディスプレイ・照明・色彩・フロアレイアウトを統合して購買体験を設計する。\nB：正しい。顧客が店内を長く回遊することで商品との接触機会が増え、衝動買い・ついで買いを促進する効果がある。スーパー・アパレル等での動線設計の基本。\nC：正しい。入口付近（ゴールデンゾーン）への新商品・季節商品・セール品の配置は来店直後の購買意欲が高い状態を活かす配置手法。奥への主力商品・日用品の配置も回遊誘導の定石。\n\n【頻出】VMDの概念とゾーニング（PP・IP・VP）、動線計画（客動線と作業動線の分離）は商業空間計画の頻出テーマ。\n【混同注意】飲食店の設計には食品衛生法（施設基準）・建築基準法・消防法等が関わるが、厨房面積比率を一律に定めた規定はない。業態ごとの設計実務上の目安と法的義務を混同しないこと。"

