"choices": [

"ア・イ",

"ア・ウ",

"ア・イ・エ",

"イ・ウ・エ"

],

"answer": 2,

"explanation": "ア：正しい。遮光カーテンの等級はJIS L 1055に基づき、1級（遮光率99.99%以上）・2級（99.80〜99.99%未満）・3級（99.40〜99.80%未満）に分類される。1級は完全遮光に近く、寝室・シアタールーム・医療施設等に使用される。\nイ：正しい。防炎カーテン（防炎物品）は炎が当たっても燃え広がりにくい防炎性能を持つが、着火しない・不燃という意味ではない。炎を取り除けば自己消火する性質（自消性）を持つ。\nウ：誤り。ダブルシェードとは1つのシェード製品内に2枚の生地（ドレープ素材とレース素材）を組み合わせたシェードタイプのウィンドウトリートメント。同一レールにドレープとレースを組み合わせるのはダブルカーテンの説明。\nエ：正しい。遮熱カーテンは特殊コーティングにより日射（赤外線）を反射・吸収し、室内への熱の侵入を抑制する。夏季の冷房効率向上・省エネに効果がある。\n\n正解はア・イ・エが正しいためCが答え。\n\n【頻出】遮光等級（1〜3級の遮光率数値）・防炎カーテンの性質（自消性・不燃ではない）・遮熱カーテンの機能の違いはカーテン選定問題として頻出。\n【混同注意】ダブルカーテン（ドレープ＋レースを別々にレール2本に吊る）とダブルシェード（1製品に2素材組み込み）は全く異なる製品・設置方法。"

