"explanation": "介護保険の住宅改修給付（介護保険法第45条）は要支援・要介護認定を受けた被保険者の居宅の改修に対して支給される給付。上限20万円（支給限度基準額）のうち9割または8割が給付され（所得により1〜2割負担）、対象工事は手すり設置・段差解消・扉の引き戸等への変更・床材の変更・洋式便器への交換等が法令で定められている。\n\nB：高齢者向け住宅における廊下の車椅子自走には一般に850〜900mm以上が必要とされる。600mmは通常の人が横向き通過できる程度の幅で、車椅子単独走行には不足。\nC：地域包括支援センターは高齢者の総合相談・権利擁護・介護予防等を担う行政機関（または委託機関）であり、インテリアコーディネーターの必置は定められていない。住環境整備の専門家は福祉住環境コーディネーター等が関わる。\nD：住宅性能表示制度の高齢者等配慮対策等級は1〜5の5段階で評価され、等級5が最高レベル（最も高い対策）を示す。「3段階・等級3が最高」は誤り。\n\n【頻出】介護保険住宅改修の上限額（20万円）・対象工事5種類・適用条件（要支援・要介護認定）はセットで必ず覚える。試験で頻繁に出題される。\n【混同注意】住宅性能表示の高齢者配慮等級は5段階（1〜5）。3段階と誤解しやすいので注意。等級の数値が大きいほど高いレベルの対策。"

