"explanation": "室内のフローリング床と屋外デッキ・テラスの床材を同系の色・素材感（例：室内ナチュラルウッドのフローリング×屋外ウッドデッキ）で合わせることで、インとアウトの視覚的境界が曖昧になり、空間の広がり・連続感が生まれる効果がある。ガラスの引き戸・大開口と組み合わせるとさらに効果的。\n\nA：テラスは地面（または1階床）と同レベルで設けた屋外の平面スペース（石・コンクリート・ウッドデッキ等）。バルコニーは2階以上の建物外壁から張り出した屋外スペース（手すり付き・屋根なし）。構造・素材・法的定義（建築基準法上の扱い）が異なり、同義ではない。\nB：天然木デッキ材の耐候性はウリン・イペなどハードウッドが高いことは正しいが、「すべて30年以上の耐用年数が保証される」という表現は誤り。杉・ヒノキのような国産ソフトウッドは防腐処理なしでは数年で劣化する場合があり、保証期間は材種・施工・メンテナンスによって大きく異なる。\nD：コンクリートブロック塀の新設は建築基準法施行令第62条の8等で高さ（2.2m以下）・厚さ・控え壁設置間隔・基礎深さ等の構造基準が定められており、一定規模以上は確認申請も必要。「確認申請不要・基準なし」は誤り。\n\n【頻出】インとアウトの視覚的連続性を意図した素材・色の統一はインテリアコーディネートの重要な提案テクニック。テラスとバルコニーの違い（高さ・位置）も問われやすい。\n【混同注意】テラス（地面レベル・地面接地）とバルコニー（2階以上・張り出し）・ベランダ（2階以上・屋根あり）の三者の違いを整理する。"

