"answer": 2,

"explanation": "内装工事の基本的な施工順序は、構造体（躯体）完成→設備工事（電気配線・給排水配管の先行配管）→内装下地工事（軽量鉄骨下地・石膏ボード等）→仕上げ工事（クロス・フローリング・塗装・建具取り付け）という流れが原則。この順序を守ることで各工程の品質確保と工程間の干渉防止が図れる。\n\nA：施工順序は下地から仕上げに向かって進める（下から上に、粗から精密に）のが原則。「仕上げから下地に向かう」という逆順は誤り。天井下地→天井仕上げ→壁下地→壁仕上げ→床仕上げという順が一般的。\nB：フローティング工法（浮き床工法）は床材を接着剤・釘を使わず浮かせた状態で敷設し、膨張・収縮を吸収できる工法だが、「下地の精度に影響されない」は誤り。下地の平滑性・水平精度が不十分だと床材が浮いたり軋んだりする問題が生じる。\nD：クロス張り替えでは既存クロス剥離後に下地の傷・凹凸をパテで平坦化する処理が必須工程であり、省略すると仕上がりに波打ち・凹凸が出る。「パテ処理省略が標準手法」は誤り。\n\n【頻出】内装工事の施工順序（躯体→設備→下地→仕上げ）と各工程の内容は頻出テーマ。クロス施工のパテ処理・フローリング工法の種類（直貼り・フローティング・根太工法）も確認すること。\n【混同注意】フローティング工法（接着・固定なし・浮かせて敷設）と直貼り工法（接着剤固定）は施工方法・長所・短所が異なる。下地精度はどちらの工法でも重要。"

