"explanation": "チャールズ・レニー・マッキントッシュ（1868〜1928年）はスコットランド・グラスゴーを拠点とした建築家・デザイナー。グラスゴー美術学校の建物やヒル・ハウスが代表作。垂直線・格子・白を基調とした繊細な色彩（白・紫・銀・黒）、アール・ヌーヴォーと幾何学的要素を融合させた独自のスタイルがウィーン分離派にも影響を与えた。\n\nB：マッキントッシュの活動拠点はパリではなくグラスゴー（スコットランド）。アール・デコ（1920〜30年代）は彼の活動時期の様式とも異なる。\nC：バウハウス第2代校長はハネス・マイヤー（第3代はミース・ファン・デル・ローエ）。マッキントッシュはバウハウスと直接の関係はない。\nD：マッキントッシュはモリスの弟子ではなく、グラスゴー美術学校で学んだ独自の建築家・デザイナー。建築・インテリア・家具・テキスタイルなど幅広い分野で活動した。\n\n【頻出】グラスゴー派のマッキントッシュとウィーン分離派（クリムト・オルブリッヒ等）の相互影響は近代デザイン史の頻出テーマ。\n【混同注意】マッキントッシュ（グラスゴー・幾何学×アール・ヌーヴォー）とモリス（ロンドン・手工芸復興）は同時代ながら異なる方向性を持つ。"

