"explanation": "家事動線はキッチン→洗面・洗濯室→物干し場・収納などの家事行為をつなぐ経路。この動線が短く・少ない方向転換で済む間取りは家事負担を大幅に軽減できる。特にキッチン・洗面室・ユーティリティの隣接配置は家事動線短縮の定石。\n\nB：プライベート動線（家族の寝室・浴室等）とパブリック動線（来客が通るリビング・玄関等）は明確に分離することが住宅計画の基本原則。交差が増えるほどプライバシーが損なわれ居住性が低下する。\nC：動線を一点に集約すると特定箇所での交通が増え、家族間の衝突や混雑が生じやすい。動線の分散・並行配置（例：キッチンへの複数アクセス）が使いやすい住宅の特徴。\nD：来客動線はプライベートゾーン（寝室・浴室）を通過させないことが住宅計画の基本。来客はパブリックゾーン（玄関・リビング・トイレ）のみで目的を達成できるよう計画する。\n\n【頻出】住宅の動線種類（家事動線・来客動線・プライベート動線）の分離・短縮の原則は間取り計画の頻出テーマ。\n【混同注意】動線の「短縮」（効率化）と「分離」（プライバシー確保）は異なる目的。用途によって優先事項が異なる点を整理して覚える。"

