"explanation": "面積効果とは同じ色でも面積が大きくなるほど明度・彩度が実際より高く（明るく・鮮やかに）感じられる視覚現象。壁紙・ペイント・床材選定では小さなサンプルで選ぶと実際に施工した際より明るく・鮮やかに仕上がるため、サンプルよりやや暗め・くすみ目の色を選ぶことが実務上の定石とされる。\n\nB：面積効果は暖色・寒色・無彩色を問わずすべての色で生じる現象。色相による限定はない。\nC：面積効果は「大きな面積ほど明るく・鮮やかに見える」現象。したがって大きな面積の壁色はサンプルより明るく・鮮やかに仕上がるため、実際にはサンプルより暗め・くすみ目の色を選ぶことが推奨される。記述の「暗く・くすんで見える」が逆。\nD：面積効果は人工照明・自然光の区別なく生じる視覚現象であり、照明条件による限定は誤り。\n\n【頻出】面積効果（大面積＝より明るく・鮮やかに見える）とその実務的対応（サンプルより暗め・くすみ目を選ぶ）はインテリア色彩計画の最頻出テーマのひとつ。\n【混同注意】面積効果の方向性：大面積→明るく・鮮やかに見える（＝実際より派手に仕上がる）という向きを逆に覚えないこと。"

