"explanation": "テクスチャーが粗い素材（コンクリート・粗面タイル・布・壁紙の凹凸）は表面の凹部に陰影が生じ、光が当たる凸部と影になる凹部のコントラストにより、全体として同じ色でも滑らかな面より暗く・くすんで見える傾向がある。素材のテクスチャーは色の見え方に大きく影響するため、実物サンプルでの確認が重要。\n\nA：光沢のある素材（鏡面）は光を反射するため同じ色でも明度が高く（より明るく）見える傾向がある。「明度が低く」は誤り。彩度については鏡面反射で鮮やかさが増して見えることが多い。\nC：素材の吸収率・反射率・表面テクスチャーの違いにより同一塗料でも色の見え方が異なる。木材（木目・吸い込み）と石膏ボード（均質な白い下地）では仕上がりの色が変わるため、プライマー・下地処理の有無も影響する。「完全に同一」は誤り。\nD：織物の色の混色は、経糸と緯糸の色が視覚的に混ざって見える「並置混色」（加法混色的に働く）に近い現象であり、絵具を混ぜる「減法混色」とは原理が異なる。\n\n【頻出】素材のテクスチャー・光沢・下地が色の見え方に与える影響はインテリアの素材選定問題で頻出。実物サンプルと小さな見本の違いと合わせて理解すること。\n【混同注意】加法混色（光の混色・重ねると明るくなる）・減法混色（絵具・色料の混色・重ねると暗くなる）・並置混色（細かい色点が距離をおいて混ざって見える）の3種類の違いを整理する。"

