"explanation": "光ダクト（ライトダクト・光導管）は内面を高反射率ミラーや反射材で覆った管・ダクトを使い、屋外の自然光を建物の地下・中央部・廊下など側窓から採光できない場所まで導く採光システム。電力を使わない点で省エネ性が高く、地下街・オフィスビルの内部ゾーン等に採用される。\n\nA：トップライトは天井面・屋根面に設ける採光窓で、側窓の約3倍の採光効果があるとされる（採光計算での係数が高い）。「採光量が少なく換気目的」は誤り。採光・換気の両方に有効で、採光効果は側窓より優れる。\nC：ハイサイドライト（高窓・クリアストーリー）は壁の上部（高い位置）に設ける横長の窓で、隣接建物・視線を気にせず採光でき室内深部まで光が届く。「壁の低い位置・地面近く」は正反対の説明。\nD：ライトシェルフは窓の外側（または内側）の中間高さに水平な棚板（反射板）を取り付け、直射日光を天井方向に反射させて室内奥まで拡散させる装置。窓の「上方」に取り付けて光を天井に向けて反射させるのが一般的であり、「下方」は誤り。\n\n【頻出】自然採光手法の種類：トップライト・ハイサイドライト・ライトシェルフ・光ダクト・アトリウムの特徴と採光原理は頻出テーマ。\n【混同注意】ライトシェルフ（窓中間部の反射板・光を天井に反射）とひさし（日射遮蔽目的）は似た形状だが目的・設置位置が異なる。"

