"explanation": "UA値（Uw値）は建物外皮（屋根・外壁・床・開口部すべて含む）を通じて逃げる熱量を外皮面積で割った平均熱貫流率（W/㎡K）。数値が小さいほど熱が逃げにくく断熱性能が高い。省エネ基準では地域区分ごとにUA値の基準値が設けられており、ZEH（ネット・ゼロ・エネルギー・ハウス）ではUA値0.6（6地域等）以下が要件の目安とされる。\n\nB：BEIは設計一次エネルギー消費量÷基準一次エネルギー消費量で算出される指標。数値が小さいほど省エネ性能が高く（基準より少ないエネルギーで済む）、ZEHではBEI0.8以下（省エネ20%以上削減）が要件のひとつ。「大きいほど優れる」「1.0以上が要件」はいずれも誤り。\nC：省エネ基準の地域区分は1〜8区分（8段階）で全国を細かく区分しており、「3つに大別」という記述は誤り。北海道・東北・関東・中部・近畿・中国・四国・九州・沖縄等の気候特性に応じた8区分が設けられている。\nD：UA値の算出にはすべての外皮要素（屋根・外壁・床・窓・ドア・熱橋等）が含まれる。開口部（窓・ドア）は特に熱損失が大きいため、除外されるという記述は誤り。\n\n【頻出】UA値（小さいほど高断熱）・BEI（小さいほど省エネ）の定義と読み方は省エネ基準の最頻出指標。数値の方向性を逆に覚えないこと。\n【混同注意】UA値とBEIは異なる指標。UA値は外皮の断熱性能、BEIはエネルギー消費量の比率を示す。どちらも「小さいほど優れる」点は共通。"

