"explanation": "水性塗料は水を主溶剤とし、乾燥時に揮発するVOCが溶剤系（油性）塗料と比べて大幅に少ない。臭気が低く・乾燥が比較的速く・刷毛の水洗いが可能で、環境・健康への負荷が少ないため住宅内装での採用が増えている。\n\nB：ウレタン塗料（ウレタン樹脂塗料）は硬化後も適度な弾力性・密着性を持ち、耐水・耐摩耗性に優れる。木部（フローリング・家具）への使用が最も多い塗料のひとつ。「柔軟性がなく脆い・木部不適」は誤り。\nC：漆喰は消石灰（水酸化カルシウム）を主成分とする伝統的な左官材料。アルカリ性による抗菌・防カビ性が正しい。また漆喰は多孔質構造により調湿機能も持つ（吸放湿性）。「調湿機能をほとんど持たない」は誤り。珪藻土と並んで調湿素材として評価されている。\nD：オイルフィニッシュは亜麻仁油・桐油等の乾性油を木材に浸透させる仕上げで、厚い塗膜を形成するのではなく木材内部に油を浸透させて保護する。木目を生かした透明・半透明の仕上げが特徴であり、「木目を完全に覆い隠す不透明仕上げ」は誤り。\n\n【頻出】塗料の種類（水性・油性・ウレタン・ラッカー・オイル）と特性、仕上げの違いは内装材料問題として頻出。\n【混同注意】オイルフィニッシュ（浸透・木目生かす）とペンキ塗り（造膜・木目隠す）の仕上がりの違いを正確に覚えること。"

