"answer": 0,

"explanation": "手織りペルシャ絨毯（イラン・トルコ・アフガニスタン等）はウールやシルクの天然繊維をノット技法で1本ずつ手で結いつけた工芸品。産地（イスファハン・タブリーズ等）・デザイン（ヘラーティ・メダリオン等）・素材・ノット密度（ラジ）により価値が異なる。天然素材は使用・洗浄を経るほど色が落ち着いて深みが増す経年変化が特徴。\n\nB：ウィルトン織りは機械織りによるパイル織カーペットで、パイル糸が基布に絡み込まれた構造。タフテッドは基布に針でパイル糸を植え込み裏面を接着する製法。製法・パイル密度・耐久性・価格帯が大きく異なる別製品。\nC：ラグ（Rug）は部屋の一部に敷く中〜大サイズの敷物を指し、床全面に敷き込む敷物はカーペット（Carpet）と呼ぶのが一般的。「ラグ＝全面敷き」は逆の説明。\nD：カットパイルは毛先がカットされており、表面が滑らかで毛足がそろった仕上がり（ベルベット・サキソニー等）。ループパイルは毛先がカットされずループ状のまま残る構造で、耐久性が高く・毛足の乱れが少ないが、カットパイルほど柔らかい手触りではない。記述が逆。\n\n【頻出】カーペットの製法（手織り・機械織り・タフテッド・ウィルトン）とパイルの種類（カット・ループ・カットアンドループ）の特性比較は頻出。\n【混同注意】ラグ（部分敷き）とカーペット（全面敷き込み）の区別、ループパイル（耐久性重視）とカットパイル（柔らかさ・高級感）の特性の違いを整理すること。"

