"造り付け収納（ビルトイン収納）は建物の構造・壁面に合わせて設計・施工された固定式の収納で、空間を無駄なく活用できるが将来の間取り変更には対応しにくい",

"システム収納はすべての住宅に規格化された統一モジュールで製造されるため、天井高・壁面幅の違いにかかわらず隙間なく設置できることが特徴とされる",

"可動棚収納は棚板を固定するピン・ダボの位置を変えることで棚の高さを調節できるもので、収納物の高さが変わっても対応できない固定式の棚より汎用性が低い",

"ウォールユニット（吊り戸棚）は天井まで収納を設けるために床から立ち上げる独立型の収納家具で、壁に固定せず自立する大型の収納棚を指す"

