"answer": 0,

"explanation": "造り付け収納（ビルトイン・作り付け）は現場で建物の寸法・形状に合わせて製作・施工する収納。空間を最大限活用でき・見た目がすっきりする利点がある反面、移動・撤去が困難で間取り変更の際に解体が必要となるデメリットがある。長期的な生活スタイルの変化を見越した計画が重要。\n\nB：システム収納はモジュール化された規格部材を組み合わせるが、天井高・壁幅は住宅ごとに異なるため、フィラー材（隙間埋め部材）・幅木欠き・天井対応部材等で調整する必要がある。「隙間なく設置できる」という万能性の記述は誤り。\nC：可動棚収納はピン・ダボの穴位置を変えることで棚板の高さを自由に変更できる。「収納物の高さ変化に対応できない」は誤りで、むしろ対応できることが可動棚最大の利点。\nD：ウォールユニット（吊り棚・吊り戸棚）は壁面に固定・取り付けて使用する棚・収納のことで、床から立ち上げる独立型収納ではない。壁面への取り付けが前提であり、「床から立ち上げる・自立する」は誤り。\n\n【頻出】収納の種類（造り付け・システム・家具・可動棚・吊り戸棚）の特性・設置方法・長短所の比較は頻出テーマ。\n【混同注意】ウォールユニット（壁面固定・吊り下げ）とフロアユニット（床置き）・トールユニット（床から天井近くまでの背の高い収納）の3者を区別して覚えること。"

