"乳幼児が過ごす居室の床材は硬さよりも見た目の美しさを優先し、硬質の大理石タイルや光沢仕上げのフローリングを選ぶことが安全性の観点から推奨されている",

"リビング・ダイニングに家族が集まりやすい「こどもが遊びながら親が家事をしつつ目が届く」一体的な空間を確保することは、育児の負担軽減と子どもの安全確保に有効とされる",

"子どもの成長を考慮した住宅計画では、子ども室を生涯変更しない固定間取りとし、完全独立した個室を乳幼児期から設けることが発達上最も望ましいとされる",

