"answer": 1,

"explanation": "リビング・ダイニング・キッチンを一体的につなぎ、親が家事をしながら子どもを見守れる空間設計は「ながら育児」を可能にし、子どもの安全確保と親の家事効率を両立できる有効な計画手法。アイランドキッチンや対面式キッチンを設けることで視線が通りやすくなる。\n\nA：乳幼児が使う居室の床材は転倒時の衝撃吸収・滑り防止を優先し、コルク・カーペット・クッションフロア等の柔らかく滑りにくい素材が推奨される。硬質の大理石タイルや光沢フローリングは転倒時に危険であり、安全性の観点から推奨されない。\nC：子ども室は乳幼児期から完全個室化するより、成長に合わせて分割・統合できる可変計画が推奨される。乳幼児期は親の近くで過ごすことが発達上重要であり、完全独立個室を乳幼児期から固定する計画が最も望ましいとはされない。\nD：建築基準法施行令第126条では、手すり子の間隔（隙間）について「11cm以下」と定められており、200mm以下という数値は誤り。11cm（110mm）以下とすることで子どもの頭部が抜けない安全寸法を確保する。\n\n【頻出】子育て住宅の計画手法（見守り空間・床材選定・可変間取り）と建築基準法の手すり子間隔（110mm以下）は頻出テーマ。\n【混同注意】手すり子の隙間寸法は110mm以下（子どもの頭部が通らない寸法）。200mmは大きすぎて危険。数値を確実に覚えること。"

