"explanation": "グループホーム（認知症対応型共同生活介護）は認知症と診断された要介護者（原則要支援2以上）が少人数（1ユニット2〜9人、最大3ユニット）で共同生活を営みながら、介護スタッフによる支援を受ける施設。介護保険法上の地域密着型サービスに位置付けられ、市区町村が指定・監督する。\n\nA：サ高住の基本的な説明（安否確認・生活相談の義務付け・賃貸借契約）は概ね正しい。ただし入居形態は必ずしも「一般の賃貸住宅」とは言い切れず、利用権方式の施設も存在する。選択肢の中ではCが最も正確。\nB：有料老人ホームは老人福祉法に基づく施設（社会福祉法ではない）。要介護認定がなくても入居できる住宅型・健康型も存在し、「要介護認定者のみ」は誤り。また介護サービスの提供形態（外部利用型・一括提供型）も種類によって異なる。\nD：特別養護老人ホームは原則として要介護3以上が入居対象であり、軽度者（要介護1・2）は原則として対象外。記述が逆になっている。\n\n【頻出】高齢者向け住宅・施設の種類（サ高住・特養・有料老人ホーム・グループホーム）と入居条件・法的根拠の違いは福祉住環境テーマの頻出問題。\n【混同注意】特養（要介護3以上が原則対象）と老健（要介護1以上・リハビリ目的）・グループホーム（認知症者・地域密着型）の対象者・目的の違いを整理すること。"

