"explanation": "デ・スティル（オランダ語で「様式」の意）は1917年にテオ・ファン・ドゥースブルフとピエト・モンドリアンらが主導したオランダの芸術運動。水平線・垂直線のみを使用し、色彩は一次色（赤・青・黄）と無彩色（白・黒・グレー）のみに限定するという極度に純化・抽象化された造形言語を特徴とする。建築・家具・グラフィックに影響を与え、バウハウスとも密接な関係があった。\n\nB：デ・スティルの代表的建築家はヘリット・リートフェルト（シュレーダー邸）やファン・ドゥースブルフ。ル・コルビュジエはスイス・フランスのモダニズム建築家で、デ・スティルとは別の流れ。サヴォア邸はル・コルビュジエの代表作だが、デ・スティルの具現化ではない。\nC：デ・スティルは曲線・有機的形態を排除し、水平・垂直の直線のみを基本とした運動。アール・ヌーヴォーの有機的曲線への反動という側面もある。\nD：シュレーダー邸はリートフェルトが設計した正しい情報だが、木造建築ではなく鉄筋コンクリート・木造・鋼材の混構造。「西洋の数寄屋」という呼称も一般的ではない。\n\n【頻出】デ・スティルの造形原則（水平・垂直・三原色＋白黒グレー）とモンドリアンの絵画・リートフェルトの家具（レッドブルーチェア）・シュレーダー邸は頻出。\n【混同注意】デ・スティル（オランダ・1917年・直線・純色）とバウハウス（ドイツ・1919年・芸術×技術）は相互影響があるが別の運動。両者の違いを整理すること。"

