"explanation": "インテリアコーディネーター資格試験は公益社団法人インテリア産業協会が主催・運営する民間資格試験。試験は一次試験（マークシート方式の学科：インテリアコーディネーションの基礎知識）と二次試験（プレゼンテーション図面作成・論文記述）の2段階で構成され、両方に合格することで資格登録できる。\n\nB：インテリアコーディネーターは民間資格（国家資格ではない）。建築士法による業務独占規定もなく、資格がなくてもインテリアコーディネート業務を行うことを法律が禁止していない。資格は専門性・信頼性の証明として機能する。\nC：インテリアコーディネーター資格の登録有効期限は登録から4年（4年ごとの更新制）で、「3年ごと」は誤り。更新には所定の単位取得・更新手続きが必要。\nD：インテリアコーディネーター試験には特定の学歴・実務経験年数による法的受験制限は設けられておらず、年齢・学歴・国籍等を問わず誰でも受験申込みができる。\n\n【頻出】インテリアコーディネーター資格の概要（実施機関・試験構成・民間資格・更新制度）は資格制度問題として頻出。\n【混同注意】国家資格（建築士・宅建士等：法的業務独占あり）と民間資格（インテリアコーディネーター：法的業務独占なし）の法的性格の違いを明確に区別すること。"

