"explanation": "デスクでのモニター作業において、モニター正面から窓の自然光が当たるとモニターへの映り込み・グレア（まぶしさ）が生じて目の疲れ・視認性低下の原因となる。窓はモニターの側面方向（側光）に配置し、直接光がモニター面や目に当たらないよう配慮することが正しい。「モニター正面から自然光を取り込むことが最も理想的」は誤り。\n\nA：正しい。ビデオ会議でのバックグラウンド（背景）管理は在宅勤務の現実的な課題。壁面を整理しやすい収納計画にし、ニュートラルな色（白・グレー・ベージュ等）でプロフェッショナルな印象を演出することが有効。\nB：正しい。在宅勤務では家族の生活音・子どもの声等が仕事の妨げになる。壁・床の吸音処理（吸音パネル・厚手カーペット等）や遮音性の高いドア（防音ドア）の採用は集中環境の確保に有効。\nD：正しい。在宅ワークでは仕事と生活の境界が曖昧になりやすく、心理的オン・オフの切り替えが困難になる問題がある。物理的・視覚的に仕事エリアを区切ることで切り替え効果が期待できる。\n\n【頻出】在宅ワーク空間のデスク周辺の採光計画（側光が基本・モニター正面への直射光は避ける）・グレア防止・防音・視覚的ゾーニングはテレワーク住宅計画の頻出テーマ。\n【混同注意】「採光が多い＝目に良い」という誤解に注意。モニター作業では光の方向・量・反射が重要であり、正面からの強い自然光は逆効果。"

