"explanation": "ウィーン分離派（Wiener Secession・ゼツェッション）は1897年にオーストリア・ウィーンで、グスタフ・クリムト・ヨーゼフ・マリア・オルブリッヒ・ヨーゼフ・ホフマンらが保守的なアカデミズム（芸術家協会）からの「分離」を宣言して結成した芸術家・建築家グループ。「芸術は全芸術に属する、芸術には自由を」を標語に掲げ、絵画・建築・工芸・グラフィック等の総合芸術を目指した。スコットランドのマッキントッシュとの交流も知られる。\n\nB：ウィーン分離派の本拠地はウィーン（オーストリア）であり、パリではない。インテリア・工芸デザインへの関与も大きく、ウィーン工房（ウィーナー・ヴェルクシュテッテ）を通じて実践した。\nC：ウィーン分離派とアーツ・アンド・クラフツの関係は思想的な共鳴はあるが、後継組織でもなく、モリスの直弟子が主要メンバーというわけでもない。独立した別の運動体。\nD：ウィーン分離派の結成は1897年で、ポストモダニズム（1970〜80年代）より大幅に早く、歴史様式の引用・折衷を理念としたわけではない。\n\n【頻出】ウィーン分離派のキーパーソン（クリムト・オルブリッヒ・ホフマン）と成立背景（アカデミズムからの分離）、マッキントッシュとの相互影響は頻出。\n【混同注意】分離派（ゼツェッション）とウィーン工房（ヴェルクシュテッテ）は関連するが別組織。ウィーン工房（1903年設立）は分離派メンバーのホフマン・モーザーらが工芸品の生産・販売を目的に設立した工房。"

