"explanation": "ナトリウムランプ（低圧・高圧）はナトリウムの輝線スペクトル（主に黄橙色の589nm付近）を主に発光する光源。低圧ナトリウムランプは単一波長に近いため演色性が極めて低く（Ra約-44〜0）、高圧ナトリウムランプも演色性はRa20〜60程度。物体の色が正確に識別できないため一般照明には不向きだが、光の透過性が高く霧中でも見えやすい特性から道路・トンネル・港湾照明等に採用されてきた。\n\nA：昼白色蛍光灯の演色性はRa80〜90程度が一般的。白色LEDにも高演色タイプ（Ra90以上・Ra97等）が多数存在し、「LEDより常に高い」という断定は誤り。現在は高演色LEDが蛍光灯を上回る製品も普及している。\nC：白色LEDは青色LEDと黄色蛍光体（主にYAG蛍光体）の組み合わせで作られ、黄色蛍光体が広い波長帯で発光するため緑色の光も含む。「緑色をまったく含まない」は誤り。植物育成用LED（赤・青波長強化型）も存在する。\nD：高圧水銀ランプの演色性はRa40〜60程度と低く、美術館・ショールーム向けではない。美術館等の高演色性を要求する用途には高演色蛍光灯・高演色LED・ハロゲンランプ等が使用される。\n\n【頻出】光源の種類（白熱球・蛍光灯・LED・ナトリウムランプ・水銀ランプ・メタルハライド）の演色性（Ra値）・色温度・用途の比較は照明計画の頻出テーマ。\n【混同注意】ナトリウムランプの低演色性と道路照明への使用は特徴的な知識。「演色性が低い光源の用途」として頻出。"

