"防犯ガラスとは強化ガラスと同義であり、どちらも割れた際に粒状に破砕することで侵入に必要な時間を大幅に増大させる機能を持つ",

"センサーライトは人感センサーで点灯する照明で、夜間の侵入者に対して心理的威嚇効果があるが、設置場所・向きが不適切な場合は逆に侵入者の作業を助けることがある",

"防犯サムターン（不正解錠防止機構付き錠）は外部からのピッキング攻撃を防ぐ目的で設けられたもので、ドアの内側からの操作方法は通常の錠と全く同じとされる"

