"explanation": "センサーライトは人の動きや熱を感知して自動点灯する照明で、侵入者に「気づかれた」という心理的威嚇効果がある。しかし設置場所・照射方向・感度が不適切な場合（例：暗い死角を照らさず、逆に侵入者が作業しやすい明るさになる位置に設置）には防犯効果が低下したり、逆効果になったりする可能性がある。設置計画の精度が重要。\n\nA：正しい記述だが、本問では選択肢の中でCが最も正確で完全な正解として位置づけられる。CPTEDの概念（自然監視・自然なアクセスコントロール・領域性の強化・メンテナンス・活動性の支援）は防犯設計の基本として重要な知識。\nB：防犯ガラスは合わせガラス（中間膜で破片を保持し貫通しにくい）を用いた製品を指し、強化ガラス（粒状破砕・加工不可）とは異なる。強化ガラスは割れたとき粒状になり破片が飛散しにくいが、割れること自体は容易で侵入時間の増大効果は防犯ガラス（合わせガラス）に比べて低い。\nD：防犯サムターンは内側の操作部を取り外し・回転・プッシュ等の特殊操作が必要な構造にし、外部からのサムターン回しによる不正解錠を防ぐもの。外部からのピッキング防止というより、ドア内側からのサムターン操作を不正に行わせないための機構。「内側からの操作が通常と全く同じ」ではなく、特殊操作が必要な製品が多い。\n\n【頻出】CPTEDの概念と具体的手法（自然監視・アクセスコントロール・領域性）は防犯設計問題の最頻出テーマ。センサーライト・防犯ガラス・ドア錠の種類も出題される。\n【混同注意】防犯ガラス（合わせガラス・割れても貫通しにくい）と強化ガラス（熱処理・粒状破砕・侵入防止効果は低い）は性能・原理が異なる。"

