"explanation": "背の高い家具の転倒は地震時の重大な怪我・死亡事故の原因となる。就寝中に倒れると逃げられないため寝室への設置は特に注意が必要。転倒防止対策として壁への固定（L字金具・突っ張り棒等）・家具配置の工夫（重心を低くする・壁に沿わせる）・転倒防止グッズの活用が推奨される。\n\nB：転倒防止グッズには壁固定型のほか、天井突っ張り型（壁への固定不要）・吸盤型・ベルト型等、賃貸でも壁に穴を開けずに使用できる製品が多数市販されている。「壁固定製品のみ」「賃貸では法律上免除」はいずれも誤り。\nC：家具用ガラスには安全ガラス（強化ガラス・合わせガラス）を使用した製品も多く存在し、「すべてのガラス家具が危険」とは言えない。また現行法（消費生活用製品安全法・SG基準等）でも一部の家具ガラスに安全基準が設けられている場合がある。\nD：耐震ラッチは地震の揺れ（横揺れ・縦揺れの両方）による引き出し・扉の開放を防止する装置。「縦揺れにのみ反応・横揺れに効果なし」は誤り。横揺れによる引き出し飛び出し防止が主な目的のひとつ。\n\n【頻出】地震対策としての家具転倒防止（固定方法・設置場所の注意点・転倒防止グッズの種類）は住宅安全計画の頻出テーマ。\n【混同注意】転倒防止対策は「壁固定のみ」ではない。賃貸住宅でも実施できる天井突っ張り型等の製品の存在を知っておくこと。"

