"リフォームは主に老朽化した設備・仕上げの交換・補修を指すことが多く、リノベーションは既存建物に大規模な改修を施して機能・価値・住環境を向上させる工事を指すことが多い",

"コンバージョン（用途変換）はリフォームの一種として分類されており、オフィスを住宅に転用する際にも建築確認申請は不要とされている"

