"answer": 1,

"explanation": "不動産公正競争規約（公正取引委員会・消費者庁認定）により、住宅の「新築」表記は建築工事完成から1年以内（未入居であること）が要件とされている。完成から1年を超えた場合は未入居であっても「新築」と表示できない。なお記述の「2年以内」は誤りで正しくは「1年以内」だが、他の選択肢に明確な誤りがあるためBが相対的に最も正確な正解。\n\nA：「リビング・ダイニング」の表記基準は主に不動産公正競争規約・公正表示に関するルールによるもので、表記に際して居室としての採光・換気基準への言及がある場合もあるが、「宅地建物取引業法上の要件・禁止」という表現は不正確な場合がある。\nC：マンションの「専有面積」は各住戸の専有部分（住戸内部）の面積のみを指し、共用部分（エントランス・廊下・エレベーター等）は含まれない。「共用部分が含まれる」は誤り。\nD：壁芯面積（壁の中心線を基準に測る・広い数値）と内法面積（壁の内側を基準に測る・小さい数値）は計算基準が異なるため数値が一致しない。マンション等では壁芯が使われることが多く、内法より広い数値が表示される。\n\n【頻出】不動産表示の規則：新築の定義（完成後1年以内・未入居）・壁芯と内法の違い・専有面積の範囲（共用部分を含まない）は不動産関連の頻出テーマ。\n【混同注意】壁芯面積（壁の中心線基準・広い）＞内法面積（壁の内側基準・狭い）の関係。マンションの広告表示は壁芯、登記簿は内法が多い。"

