"explanation": "御影石（花崗岩）は硬度・耐久性に優れた外構・アプローチ素材として広く使われるが、磨き（ポリッシュ）仕上げは表面が滑らかで光沢があり、濡れると非常に滑りやすく危険。屋外の歩行面・アプローチには、表面に凹凸をつけたバーナー仕上げ（炎で表面を荒らす）・ビシャン仕上げ（ノミで叩く）・サンドブラスト仕上げ等の粗面加工品が安全性の観点から推奨される。\n\nB：コンクリートインターロッキングブロック（ILB）はブロック間に砂を充填してジョイントする工法で、地盤の変動・沈下・不陸が生じた際にブロックを一時的に撤去して修正・再敷設が比較的容易なことが利点のひとつ。「地盤変動を吸収できず不陸が生じやすい欠点」という記述は、むしろアスファルト・コンクリート舗装との比較でILBの利点（補修が容易）を誤解した記述。\nC：人工芝は天然芝と比べて保水性が低く（プラスチック製で水分を保持しない）、夏季の表面温度は天然芝より大幅に高くなる（60℃以上になることも）という欠点がある。「天然芝と同等の熱吸収性・同程度の温度」は誤り。\nD：ハードウッド（ウリン・イペ・セランガンバツ等）は硬度が非常に高い（鉄より重い・釘が刺さりにくい）ため、通常のノコギリや釘では加工・施工が困難で専用の工具・ビスが必要。「軟らかく加工に適した素材」は誤り。\n\n【頻出】外構素材の特性（御影石の仕上げ種別と滑り安全性・インターロッキングの補修性・人工芝の熱問題・ハードウッドの硬度）は外構・エクステリア計画の頻出テーマ。\n【混同注意】御影石の仕上げ：磨き仕上げ（屋内・光沢・滑りやすい）vs バーナー仕上げ（屋外・粗面・滑りにくい）の用途の違いを確実に区別すること。"

