"両者の希望を折衷した「ジャパンディ（北欧×和モダン）」スタイルの可能性を両者に提示し、共通する価値観（自然素材・シンプル・落ち着き）を軸に両者が納得できる方向性を模索する",

"夫婦の意見が異なるため、LDKと寝室を全く異なるスタイル（LDK＝北欧風・寝室＝和風）に完全に分離し、空間の統一感を犠牲にして個別の希望を最優先する",

