"answer": 1,

"explanation": "アップサイクル（Upcycling）は廃材・古材・不用品を単に材料として再処理（ダウンサイクル）するのではなく、創造的な加工・デザインを加えることで元の価値以上の製品・インテリアに生まれ変わらせる手法。古材をテーブルトップに、廃工場の部材を家具に転換する等の事例が増えており、サステナブルインテリアの文脈で注目されている。\n\nA：サステナブルインテリアは普遍的デザインのみでなく、素材の持続可能性（再生可能素材・環境配慮素材の選択・長寿命設計・廃棄時の環境影響等）も重要な要素として含む。「環境負荷は考慮対象外」は誤り。\nC：FSC（Forest Stewardship Council）認証は持続可能な森林管理を認証する国際的な制度で、「管理された森林由来の木材・紙製品」に表示される。「ファッション業界の繊維素材認証」ではなく木材・森林管理の認証制度。\nD：天然素材が常に合成素材より環境負荷が低いとは言えない。例えば綿の栽培には大量の水・農薬が必要な場合があり、一方でリサイクル可能な合成素材もある。環境負荷は製造プロセス・輸送・耐久性・廃棄方法等を総合的に評価する必要がある。「すべての天然素材が優れている」という断定は誤り。\n\n【頻出】サステナブルインテリアの概念（アップサイクル・リサイクル・FSC認証・長寿命設計・環境配慮素材）は近年の試験で出題が増えている重要テーマ。\n【混同注意】アップサイクル（価値向上的再生）とリサイクル（素材に戻して再利用・価値は下がる場合も）・ダウンサイクル（品質・価値が下がる形での再利用）の3者の違いを整理すること。"

