"explanation": "近代建築の5原則を提唱したのはル・コルビュジエ（スイス生まれ・フランス活動）であり、フランク・ロイド・ライトとは別人。ライトのプレーリースタイルはル・コルビュジエの5原則とは独自に発展した様式であり、「5原則のアメリカでの実践」という記述は誤り。ライトは有機建築を標榜し、自然・敷地・建物の一体性を重視した。\n\nA：正しい。プレーリースタイルは水平強調の低い屋根（広い軒の出）・横連続窓・レンガ・自然素材による重心の低いシルエットが特徴。\nB：正しい。ライトは暖炉（ハース）を家族の集いの中心として配置し、その周囲に空間を展開する設計手法を多用した。\nC：正しい。イリノイ州シカゴ郊外のプレーリー（大草原）の水平に広がる景観からインスピレーションを得た様式で、建物が大地と一体化するような水平性が特徴。\n\n【頻出】ライト（プレーリースタイル・有機建築・水平強調）とル・コルビュジエ（5原則・モデュロール・白い建築）の違いは近代建築史の最頻出比較問題。\n【混同注意】「水平連続窓」はル・コルビュジエの5原則の一要素でもあり、プレーリースタイルにも水平連続窓が見られるが、その思想的背景・理由が全く異なる点を理解すること。"

