"answer": 2,

"explanation": "ジャロジー窓（よろい戸窓・ガラスルーバー窓）はガラスの薄い羽根板（ルーバー）を水平に並べた窓で、ルーバーの角度調整により通風を細かく制御できる。しかしルーバー間に必ず隙間が生じるため閉鎖時でも気密性が低く、断熱性・防犯性にも劣る。「閉鎖時の気密性が高い」は誤り。温暖な地域・換気重視の空間で使用されることが多い。\n\nA：正しい。FIX窓は開閉不可のため換気はできないが、開口部がないことで気密性・水密性が最も高く、大きな開口で採光・眺望を確保できる。\nB：正しい。オーニング窓（突き出し窓）は上辺の軸を中心に外側へ開くため、開放時に庇の役割をして雨が直接入りにくい。雨天でも換気できる利点がある。\nD：正しい。ピボット窓は縦軸回転タイプ（窓中心付近の縦軸で回転）や水平軸回転タイプがあり、ガラス面が室内外に突出する独特の動きがデザイン的な特徴となる。清掃しやすい利点もある。\n\n【頻出】窓の種類と特性（開閉方式・気密性・換気性・防雨性）の比較はインテリア計画の頻出テーマ。特に気密性の高低（FIX＞引き違い＞ジャロジー）の序列を覚えること。\n【混同注意】ジャロジー窓（通風優秀・気密性低）とFIX窓（気密性高・換気不可）は気密性が正反対。混同しやすい組み合わせとして出題される。"

