"トーンオントーン配色とは異なる色相を高彩度から低彩度へとグラデーション状に変化させた配色で、彩度の変化が視覚的なリズムを生む",

"フォカマイユ配色とは異なる色相の鮮やかな色を多数組み合わせた配色で、賑やかで活気のある空間演出に最適とされる",

