"explanation": "防火ドア（防火設備用ドア）は建築基準法第2条・令第109条に基づき、防火設備（20分遮炎性能）または特定防火設備（60分遮炎性能）としての大臣認定・型式認定が必要。防火区画・防火地域の建物等では認定を受けた製品を使用することが義務付けられており、一般のドアを代用することはできない。\n\nA：フラッシュ戸は薄い合板を芯材（ペーパーコア・ハニカムコア・ランバーコア等）の両面に張り付けた構造で、「木製框組みの芯材に合板を張り付けた」という記述は框組みドアの構造に近い。フラッシュ戸の特徴（軽量・反りにくい・量産性・コストの低さ）は正しい部分もあるが、構造の説明が不正確。\nB：框組みドア（パネルドア）は木製の框（たて・よこの骨組み）と鏡板（パネル）で構成される伝統的なドア形式で、「芯材なし」という点はある意味正しいが、密閉性が「高い」とは言えない。むしろフラッシュ戸の方が面として平滑で気密性が確保しやすい場合がある。\nD：バリアフリー計画では開き戸より引き戸・折れ戸が推奨されることが多い。引き戸はドアの前後に立つスペースが不要で、車椅子使用者・高齢者が出入りしやすい。「開き戸が常に推奨される」は誤り。\n\n【頻出】防火ドアの法的要件（防火設備・特定防火設備の認定）とフラッシュ戸・框組みドアの構造の違いは建具問題の頻出テーマ。\n【混同注意】防火設備（20分遮炎）と特定防火設備（60分遮炎）は要求性能が異なる。設置箇所（防火区画の種類）によって必要な性能が異なることを覚えること。"

