"explanation": "鋼材は高温（500〜600℃程度）になると急激に強度が低下（約50%以下）するため、火災時に建物が倒壊するリスクがある。建築基準法では耐火建築物の要件として、鉄骨部材に耐火被覆（吹付けロックウール・耐火ボード被覆・耐火塗料等）を施すことが定められており、超高層・特定用途建築物では法的義務となる。\n\nB：軽量鉄骨（板厚6mm未満の薄板鋼材）は低層住宅（プレハブ住宅等）に使用される構造形式で、重量鉄骨（板厚6mm以上）とは耐力・適用規模が大きく異なる。「超高層建築に適した」「重量鉄骨と同等」は誤り。\nC：鉄骨の溶接接合部は現場溶接・工場溶接ともに品質管理が非常に重要で、超音波探傷検査・外観検査等による品質確認が求められる。「現場での品質管理が不要」は誤り。接合部の欠陥は構造安全性に直結する。\nD：H形鋼はウェブ（垂直板）とフランジ（水平板）で構成されるが、断面の形状により曲げ剛性の方向性がある（フランジ方向に強い）。「全断面が均一な圧縮強度」は誤りで、使用方向によって強度特性が異なる。\n\n【頻出】鉄骨構造の耐火被覆の必要性・軽量鉄骨と重量鉄骨の使用規模の違い・溶接接合の品質管理は構造材料問題の頻出テーマ。\n【混同注意】S造（鉄骨）の火災弱点（高温で強度低下）はRC造（コンクリートが鉄筋を熱から保護）と対比して覚えること。"

