"answer": 0,

"explanation": "ハンス・J・ウェグナー（1914〜2007年）はデンマークの家具デザイナーで、Yチェア（CH24・Wishbone Chair・1950年）は曲木の背もたれ（Y字形・ウィッシュボーン形状）と天然のペーパーコード（紙ひも）を編んだ座面が特徴。カール・ハンセン＆サン社が現在も製造・販売を継続している北欧デザインの不朽の名作。\n\nB：アントチェア（Ant Chair・1952年）はデンマークのアルネ・ヤコブセンが設計した成形合板＋スチール脚の椅子。アルヴァ・アアルトはフィンランドの建築家・デザイナーで代表作はパイミオチェア・スツール60等。記述の「アントチェア＝アアルト設計」は誤り。\nC：ヴァーナー・パントン（1926〜1998年）はデンマーク出身で、パントンチェア（Panton Chair）はプラスチック（ポリエステル等）の一体成形で作られた椅子であり、「木材のみで構成」は誤り。初のプラスチック一体成形椅子として1967年に発表。\nD：エッグチェア（Egg Chair・1958年）はアルネ・ヤコブセン（デンマーク人）が設計したもので、コペンハーゲンのSASロイヤルホテルのロビー・客室のために制作。デンマーク王立劇場ではなく、またウール地表張りのバリエーションはあるが「ウール地のみ」という記述は限定的すぎる。\n\n【頻出】北欧デザインの代表的デザイナーと作品：ウェグナー（Yチェア）・ヤコブセン（アントチェア・エッグチェア・セブンチェア）・アアルト（パイミオチェア・スツール60）・パントン（パントンチェア）の組み合わせは最頻出。\n【混同注意】アルネ・ヤコブセン（デンマーク）とアルヴァ・アアルト（フィンランド）は名前が似ているが全くの別人。国籍・代表作も全く異なる。"

