"explanation": "介護保険の住宅改修を活用した住宅改善では、ケアマネジャー（介護支援専門員）が介護保険申請の窓口・支援計画作成の主体となるが、インテリアコーディネーターは住環境の専門家として具体的な改修プランの立案・素材選定・施工監理等で重要な役割を担う。介護保険対象工事（5種類）を把握した上でケアマネジャーと連携し、保険対象内外の工事を組み合わせた包括的な改修提案が理想的な対応。\n\nB：インテリアコーディネーターは介護保険住宅改修の申請手続きの代理こそできないが、改修計画の立案・施工業者との調整・空間設計の専門的サポートを行うことができ、「一切関与できない」は誤り。福祉住環境コーディネーターとの連携も有効。\nC：介護保険の住宅改修給付は自己負担が原則1〜3割（所得に応じて）あり、「自己負担ゼロ」は誤り。上限20万円の1〜3割を施主が負担する。また20万円を超える部分は全額自費となる。\nD：築40年の木造住宅でも全面建て替えを「最初に最も効果的として必ず提案する」ことは、施主の意向（部分改修の希望）・経済的負担・工期等を無視した一方的な提案であり不適切。まず施主の意向を確認した上で選択肢を提示するのが基本。\n\n【頻出】介護保険住宅改修（対象5工事・上限20万円・自己負担1〜3割）とケアマネジャーとの連携・インテリアコーディネーターの役割は福祉住環境の頻出テーマ。\n【混同注意】介護保険住宅改修の自己負担割合（1〜3割で所得により異なる）と給付の上限額（20万円）の関係を正確に理解すること。「20万円全額給付＝自己負担ゼロ」は誤り。"

