"question": "次の照明計画に関するア〜エの記述のうち、正しいものの組み合わせはどれか。\nア：タスクライティングとは作業面（書類・調理台・手元等）を重点的に照らす局部照明で、全般照明と組み合わせることで省エネと視作業性の向上を同時に実現できる\nイ：アクセントライティングとはアート作品・植物・テクスチャー壁等の特定の対象を際立たせるための照明で、対象物の照度を周囲の3〜5倍以上にすることでドラマティックな演出効果が生まれる\nウ：アンビエントライティングとは室内の全般照明として空間全体を均一・柔らかく照らす基礎的な照明で、直接照明・間接照明どちらの方式でも実現できる\nエ：ペンダントライトは天井から吊り下げる照明器具で、高さ調整ができる製品では空間の用途に応じた照射高さの変更が可能で、ダイニングテーブルの直上に設置する場合の適切な高さの目安は床面から1500mm程度とされる",

