"answer": 2,

"explanation": "ア：正しい。タスクライティング（局部照明）は作業に必要な部分のみを明るくする手法で、全般照明（アンビエント）を低照度に抑えて省エネしながら作業面の視認性を確保するタスク・アンビエント照明として普及している。\nイ：正しい。アクセントライティングは特定の対象を強調するため、周囲の照度に対して3〜5倍（一説には5〜10倍）の照度差をつけることで焦点が際立ち、ドラマティックな空間演出が生まれる。\nウ：正しい。アンビエントライティング（環境照明・全般照明）は空間の基礎的な明るさを確保する照明で、天井の直接照明（シーリングライト等）や間接照明（コーブ照明・反射板利用等）のどちらの方式でも実現できる。\nエ：誤り。ダイニングテーブルの上のペンダントライトは、テーブル面から700〜800mm程度の高さ（床面からではなく、テーブル面から）に設置するのが一般的な目安。テーブル面の高さ（約700〜750mm）に700〜800mmを加えると床面から約1400〜1550mmとなり、「床面から1500mm程度」という数値は概ね近いが、ペンダントの設置高さはテーブル面からの距離で管理するのが正確。\n\n正解はア・イ・ウが正しいためCが答え。\n\n【頻出】照明の3層計画（アンビエント・タスク・アクセントの組み合わせ）はインテリア照明計画の基本概念として最頻出テーマ。\n【混同注意】ペンダントライトのダイニング設置高さは「テーブル面からの距離（700〜800mm）」で管理するのが実務の基本。「床面からの高さ」で考えると混乱しやすい。"

