"explanation": "「S（サービスルーム・納戸）」は建築基準法の居室としての要件（主に有効採光面積が床面積の1/7以上等）を満たさない部屋に使われる表記。採光・換気が不十分なため「居室」と呼べない部屋を、不動産表示上は「S」「納戸」「サービスルーム」等と表記することが慣行となっている。\n\nA：DK（ダイニングキッチン）の最低面積基準について、不動産公正競争規約では住戸の居住人数に応じて基準が設けられており「6畳以上」という一律基準ではない。また「住宅性能表示規則でのDK最低基準6畳」という記述は正確ではない。\nB：リビング（L）の定義が建築基準法で規定されているわけではない。建築基準法は「居室」の採光・換気基準を定めるが、「リビング」という用語の定義を法定していない。間取り表記はあくまで不動産業界の慣行による。\nD：間取り表記の基準は日本建築学会が法定しているわけではなく、業界の慣行によるもの。「2LDK」の実際の広さ・形状は物件によって様々であり、表記が統一的に保証するわけではない。\n\n【頻出】間取り表記のS（サービスルーム・採光不足の非居室）・DK・LDKの違いと建築基準法の居室要件（採光1/7以上）の関係は不動産・住宅計画問題の頻出テーマ。\n【混同注意】「S」は広さが小さいのではなく、建築基準法上の「居室」の要件（特に採光基準）を満たさない部屋に使われる表記。広くてもSと表記される場合がある。"

