"explanation": "インテリアデザインにおける「空間の物語性（ナラティブ・コンセプト）」とは、空間全体に一貫したテーマ・ストーリー（例：「旅好きの家族が世界中から集めた素材と記憶が積み重なった家」「シンプルな日本の美意識と現代の機能を融合した空間」等）を持たせることで、訪れる人・住む人が一貫した印象・感情・体験を得られるよう設計する概念。素材・色・照明・家具・小物が一つの物語として調和することで、単なる「きれいな部屋」を超えた豊かな空間が生まれる。\n\nB：空間の物語性は商業施設・ホテルだけでなく、一般住宅でも「施主の個性・価値観・ライフスタイルを反映した物語」として適用できる概念。住宅コーディネートでも最も重要な設計概念のひとつ。\nC：空間の物語性は特定のブランドへの統一を意味しない。むしろ異なる時代・産地・素材のアイテムが一つのテーマのもとで調和することで、より豊かな物語性が生まれる場合が多い。\nD：施主の価値観・生活スタイルを無視してコーディネーターのコンセプトを押し付けることは職業倫理に反する。物語性のある空間は施主との深いヒアリングを通じて「施主の物語」を発見し、それをデザインで具現化することで生まれる。\n\n【頻出】インテリアコーディネートにおけるコンセプト設定・空間の統一感・物語性の考え方はコーディネート理論の発展的テーマとして近年出題が増えている。\n【混同注意】「物語性」は文学的な概念だが、インテリアでは「統一されたコンセプト・テーマ・感情的体験」の意味で使われる。施主の個性・価値観に根ざした物語を作ることがコーディネーターの創造的な役割。"

