"explanation": "ポップアート（Pop Art）は1950年代にイギリス（リチャード・ハミルトン等）で始まり、1960年代にアメリカ（アンディ・ウォーホル・ロイ・リキテンスタイン等）で大きく花開いた芸術運動。マス消費社会の広告・コミック・商品を芸術の対象とし、鮮やかな原色・太い輪郭・大胆なグラフィック表現が特徴。インテリアでは大胆な壁面グラフィック・明るい原色使い・工業製品のインテリアへの取り込みという形で影響を与えた。\n\nB：印象派はフランスの19世紀後半の絵画運動（モネ・ルノワール等）でポップアートとは全く異なる起源・時代・内容を持つ。印象派がポップアートの直接の起源という記述は誤り。\nC：ポップアートの特徴は無彩色・ミニマルではなく、まさにその反対の鮮やかな色彩・大胆な図案・マスメディア的なイメージの使用が特徴。ミニマリズムとは対極にある運動。\nD：ポップアートはイタリアに限定されず、起源はイギリス・アメリカにあり、世界中のインテリアデザイン・グラフィック・プロダクトデザインに広く影響を与えた。\n\n【頻出】ポップアートの起源（イギリス→アメリカ）・代表的アーティスト（ウォーホル・リキテンスタイン）・インテリアへの影響（鮮やか色彩・グラフィカルなデザイン）はデザイン史の頻出テーマ。\n【混同注意】ポップアート（大胆色彩・マス文化）とミニマリズム（極度の簡素・装飾排除）は方向性が正反対。どちらも現代インテリアに影響を持つが価値観が全く異なる。"

