"explanation": "デコンストラクティビズム（Deconstructivism）は1988年のMoMAの展覧会「Deconstructivist Architecture」以降に認知された建築様式。フランス哲学者ジャック・デリダの脱構築思想の影響を受け、従来の建築の秩序（対称・安定・一体性）を意図的に崩した断片化・傾斜・衝突・歪みのある動的な形態が特徴。フランク・ゲーリー・ザハ・ハディド・レム・コールハース・ダニエル・リベスキンド等が代表的建築家。\n\nB：デコンストラクティビズムはバウハウスの機能主義とは対極にある運動で、1980年代以降に台頭した。バウハウスの幾何学純粋主義・機能主義との関係はない。\nC：ビルバオ・グッゲンハイム美術館（1997年）はチタン製の有機的な曲面パネルを多用した奇異な形状で知られる。「伝統的な石造り方形建築」は全くの逆で、その革新的デザインがビルバオ効果（都市再生の象徴）として世界的に注目された。\nD：デコンストラクティビズムはデリダの脱構築哲学と密接な思想的関係があるとされており、「全く無関係」は誤り。哲学的概念を建築形態に翻訳した運動として理解されている。\n\n【頻出】デコンストラクティビズムの特徴（断片化・傾斜・歪み）と代表建築家（ゲーリー・ハディド等）・デリダとの思想的関係は近代建築史の頻出テーマ。\n【混同注意】デコンストラクティビズム（解体・歪み・動的）とポストモダン（歴史引用・折衷・装飾復権）・ミニマリズム（極度の簡素）は全て異なる現代の建築潮流。"

