"explanation": "FRP浴槽は軽量（20〜30kg程度）・成形が自由で様々な形状・色が実現でき・コストが比較的低いため住宅用浴槽の中で最も普及している。一方、鋳物ホーロー浴槽（鋳鉄に琺瑯加工）は重量が大きい（100〜150kg以上）分、熱容量が大きく蓄熱性・保温性に優れる。FRPはホーロー鋳物より蓄熱性が劣るため、湯冷めしやすいという欠点がある。\n\nB：節水型シャワーヘッドは水流の絞り込みのほか、空気混合・細かい噴霧・水流のパルス化等の技術により、水圧・使用感をほぼ維持しながら節水を実現する製品が多く存在する。「使用感が著しく低下する」は誤り。\nC：浴室への換気扇設置は建築基準法で禁止されておらず、むしろ換気・防カビ・湿気除去のために積極的に推奨・採用される設備。シックハウス対策の24時間換気に組み込まれることも多い。\nD：エコキュートは追い炊き機能を持つ製品が多数市販されており（ヒートポンプで沸かしたお湯を循環させる追い炊き）、「技術上不可能」は誤り。エコキュート＋追い炊き対応の浴槽の組み合わせは一般的に普及している。\n\n【頻出】浴槽素材の比較（FRP・ホーロー鋳物・人工大理石・ステンレス）と各素材の蓄熱性・重量・コストの違いは浴室設備問題の頻出テーマ。\n【混同注意】FRP浴槽（軽量・低コスト・保温性低め）とホーロー鋳物浴槽（重量・高コスト・保温性高い）の性能の違いを対比して覚えること。"

