"筋交いは柱と梁の間に水平に渡す横架材で、主に床荷重（鉛直荷重）を柱に伝える役割を持ち、地震力（水平荷重）には抵抗しない部材とされる",

"胴差しは1階と2階の間に設ける水平部材で、2階の床組を支える役割と柱を水平方向に繋いで軸組の安定を確保する役割を持つが、地震力への抵抗機能は持たない",

"垂木は小屋組における棟木から軒桁に向かって斜めに掛け渡す部材で、屋根荷重を支える役割と外壁の骨組み（縦材）としての役割を兼ねるとされる"

