"explanation": "VE（Value Engineering：バリューエンジニアリング）は「必要な機能を確実に達成しつつコストを低減する」体系的な手法。インテリアコーディネートでは、同等以上の意匠・耐久性を持つ代替材料（例：天然石の代わりに高品質な石目調磁器質タイル）・施工工程の合理化・規格品の活用等がVEの具体例。施主の予算制約のなかで品質を最大化する提案技術として重要。\n\nB：工事費削減の要求に対してコーディネーターは、施工会社への値下げ交渉だけでなく、仕様グレードの変更・素材の見直し・工事範囲の優先順位付け等の提案が業務の核心部分。「仕様変更提案が業務範囲外」は誤り。\nC：概算見積りは設計初期・方向性確認段階で大まかな費用を算出するもの（±20〜30%の精度）。詳細見積りは仕様確定後に各工種・各材料の数量・単価を積算した精度の高いもの。両者は全く異なる書類で作成時期・精度が異なる。\nD：材料費と施工費の割合は工事の内容（素材グレード・施工の複雑さ・工法）によって大きく異なり、一律の法律規定は存在しない。\n\n【頻出】VEの概念（機能維持・コスト削減）と具体的な手法・概算見積りと詳細見積りの違いはコスト管理問題の頻出テーマ。\n【混同注意】VE（機能を下げずにコスト削減）とCD（コストダウン：単純な仕様・品質の引き下げ）は異なる概念。コーディネーターが目指すべきはVEによる品質とコストの両立。"

