"explanation": "押出法ポリスチレンフォーム（XPS：styrofoam等）は発泡ポリスチレンを押出成形した断熱材で、独立気泡（気泡が独立して連続していない）構造により吸水率が極めて低い。熱伝導率も低く、地下外壁・基礎外断熱・屋上断熱・外断熱等の湿潤環境・荷重がかかる部位にも使用できる。\n\nA：グラスウールは吸湿すると断熱性能が大幅に低下し、乾燥しても繊維の変形等により完全に元の性能に戻らない場合がある。「吸湿しても性能が回復する」は誤り。施工時の防湿処理が重要な理由はここにある。\nC：吹付け硬質ウレタンフォームは現場で液状原料を吹き付けて発泡・硬化させる工法で、複雑な形状・継ぎ目・コーナー部等にも隙間なく断熱層を形成できることが最大の特徴。「複雑な箇所に均一な断熱層を形成できない」は誤り。\nD：グラスウールは溶融ガラス繊維から、ロックウールは玄武岩・スラグ等の岩石・鉱物繊維から製造される全く別の原料の断熱材。ロックウールは耐火性（使用可能温度）がグラスウールより優れている等、性能差がある。「同一原料の姉妹製品・性能差なし」は誤り。\n\n【頻出】断熱材の種類（グラスウール・ロックウール・XPS・EPS・硬質ウレタン）と特性（熱伝導率・吸水率・耐火性・施工性）の比較は建材問題の頻出テーマ。\n【混同注意】グラスウール（ガラス繊維・吸湿弱点あり）とロックウール（岩石繊維・耐火性が高い）は同じ繊維系断熱材だが原料・耐熱性・比重が異なる別製品。"

