"answer": 3,

"explanation": "ア：正しい。ダボ（Dowel）は木製・金属製の円柱ピンで、接合面の両側に穴を開けてダボを挿入し位置決め・接合する技法。棚板の固定だけでなく、木工接合の補強にも広く使われる。\nイ：正しい。ほぞ（Tenon）継ぎは木材の端に「ほぞ（突起）」を作り、相手材の「ほぞ穴（Mortise）」に差し込む伝統的接合法。接着剤と組み合わせると高い引き抜き強度が得られ、椅子の貫・横桟・建具の框組み等に多用される。\nウ：正しい。カムロック式（コンフィルマート・カム式ノックダウン金具）はボルトとカム（偏心カム）を組み合わせた脱着可能な連結金具。IKEAをはじめとするフラットパック家具で世界的に普及しており、六角レンチで簡単に組み立て・分解できる。\nエ：正しい。蟻継ぎ（Dovetail Joint）は台形（扇形）断面のほぞと溝を組み合わせた接合法で、引き抜き・引っ張り方向の力に高い抵抗力を発揮する。引き出しの四隅・箱物家具（チェスト・キャビネット等）の伝統的な高品質接合法として知られる。\n\n全ての記述が正しいためDが答え。\n\n【頻出】木工家具の接合技法（ダボ・ほぞ継ぎ・蟻継ぎ・カムロック・スプライン等）の特徴・用途・強度特性は家具構造問題の頻出テーマ。\n【混同注意】蟻継ぎ（引き抜き強度が高い・伝統技法・手間がかかる）とカムロック（脱着可能・量産家具向き）は全く異なる接合思想に基づく。"

