"explanation": "グリーンウォッシング（Greenwashing）は「グリーン（環境に良い）」と「ホワイトウォッシング（事実を白塗りして隠すこと）」を合わせた造語。企業が製品・サービスや企業活動について、実際の環境配慮の程度以上に「環境に優しい・サステナブル」と宣伝・表示する行為。消費者の判断を誤らせる問題行為として国際的に批判され、適切な規制・認証制度の整備が進んでいる。\n\nA：正しい記述だが、本問ではDが最も正確・完全な正解として位置づけられる。サーキュラーエコノミーのインテリア産業への適用（モジュール設計・修理可能設計・素材回収スキーム等）は重要な概念。\nB：REACH規制はEUの化学物質登録・評価・認可・制限規制で、EUへ輸出する製品（日本製家具・内装材料を含む）にも適用される。「日本産業には一切影響しない」は誤りで、EU向け輸出製品には対応が必要。\nC：SDGsは17の目標・169のターゲットを持つ包括的な国際目標で、住宅・建設（目標11：住み続けられるまちづくり・目標9：インフラ等）・エネルギー（目標7）・気候変動（目標13）等、インテリア・住宅産業と密接に関連する目標が多数含まれる。\n\n【頻出】グリーンウォッシングの定義・サーキュラーエコノミーのインテリアへの適用・SDGsとインテリア産業の関連は近年の出題増加テーマ。\n【混同注意】グリーンウォッシング（実態より誇張した環境訴求）とサステナブルマーケティング（適切な環境訴求）の区別・グリーンウォッシングが批判される理由（消費者欺瞞）を正確に理解すること。"

