"explanation": "フィスカルス（Fiskars）は1649年にフィンランド南西部のフィスカルス村で設立された北欧最古の企業のひとつ。1967年に発売されたオレンジ色のハンドルを持つプラスチックグリップ鋏は、人間工学的デザイン・持ちやすさ・視認性の高い橙色で世界中に普及し、鋏のデザインアイコンとして博物館にも収蔵されている。現在はブランドグループとしてIittala・Arabia・Royal Copenhagen等を傘下に持つ。\n\nA：マリメッコ（Marimekko）の創業年は1951年で正しい。大胆なプリントテキスタイルで知られ、ウニッコ（ケシの花）・キヴェット等の人気パターンはインテリアファブリック・クッション・食器等に展開されている。この選択肢の内容は正しいが、本問ではDが最も正確な正解。\nB：イッタラ（Iittala）はフィンランドのガラスウェアブランド（1881年フィンランドのイッタラ村創業）。アルヴァ・アアルトが1936年に設計したアアルト・ベース（フィンランディア・ベース）はイッタラの代表作。「スウェーデン発祥・アアルトと無関係」はいずれも誤り。\nC：アラビア（Arabia）はフィンランドの陶磁器ブランドで、カラフルで独創的なデザインの食器・陶磁器を多数製造している。「モノクロのみ・カラフル製品なし」は誤り。\n\n【頻出】北欧デザインブランドの国籍・代表製品・デザイナーとの関係：マリメッコ・イッタラ・アラビア・フィスカルス（フィンランド）・ロイヤルコペンハーゲン（デンマーク）等は頻出テーマ。\n【混同注意】イッタラ（フィンランド・ガラス）とロールストランド（スウェーデン・陶磁器）・ロイヤルコペンハーゲン（デンマーク・陶磁器）等の国籍と素材の違いを整理すること。"

