"explanation": "民藝運動（Mingei Movement）は思想家・美学者の柳宗悦（1889〜1961年）が1920年代に提唱した日本発の美の運動。「民藝」は民衆的工芸の略で、名もない職人が日常生活の必要から生み出した器・布・家具等の手工芸品に宿る「用の美（使うためのものに宿る美）」を発見・評価した。陶芸家の河井寬次郎・濱田庄司・版画家の棟方志功等も参加。現代の和モダン・ジャパンディインテリアの精神的背景にも通じる。\n\nB：民藝運動は手工芸・職人技術の価値を再評価する運動で、機械大量生産品を称揚したわけではない。機械生産への反省としての側面もあり、アーツ・アンド・クラフツ運動との思想的共鳴もある。\nC：民藝運動の創始者は柳宗悦（日本）。ハンス・J・ウェグナーはデンマークの家具デザイナーで無関係。\nD：民藝運動の「用の美」・素材への敬意・日常道具への美意識は現代の和モダンインテリア・クラフト家具・手仕事の復権トレンドに通じており、現代インテリアへの影響は続いている。\n\n【頻出】柳宗悦と民藝運動（用の美・手工芸の価値・日本の伝統美意識）はインテリア史の頻出テーマ。アーツ・アンド・クラフツ運動との思想的比較も問われる。\n【混同注意】民藝運動（日本・柳宗悦・日常工芸の美）とアーツ・アンド・クラフツ運動（イギリス・モリス・手工芸復興）は類似した精神を持ちながら異なる文化・地域から生まれた別々の運動。"

