"explanation": "洗面脱衣室は洗面台・洗濯機・脱衣スペースを集約する多機能室。洗面台のみ（幅600〜900mm）と洗濯機（幅約600mm）を並べただけでも2〜3㎡が必要で、収納（リネン庫・タオル収納等）を加えると4〜5㎡以上確保することで快適な動線と使いやすさが実現する。標準的な2畳（約3.6㎡）では必要最低限の機能は確保できる。\n\nB：洗面台の鏡は顔の確認だけでなく、ヘアセット・全身チェック・服の確認等に使われる場合が多い。全身鏡を設けることはむしろ利便性向上として推奨されるケースが多く、「顔のみで十分・全身鏡不要が原則」という記述は誤り。\nC：洗面脱衣室の床材としてカーペットは耐水性が低く・カビが発生しやすいため推奨されない。むしろ防水性・耐水性・清掃のしやすいタイル・クッションフロア・防水フローリングが標準的。「カーペットが最も衛生的・法律で他素材変更不可」は誤り。\nD：洗濯機用防水パン（排水受け皿）は水漏れ対策として推奨されるが、設置を義務付けた建築基準法の規定は存在しない。防水パンなしの設置も実態として行われており、「全面禁止」は誤り。\n\n【頻出】洗面脱衣室の設計面積の目安・推奨床材（耐水性素材）・収納計画（洗面台まわりの収納・リネン収納等）は水回り計画の頻出テーマ。\n【混同注意】洗面脱衣室の床材は「耐水性」が最優先選定基準。カーペット（耐水性低・清掃困難・カビリスク）は水回りには不適切だが法規制はない点を理解すること。"

