"explanation": "コールドドラフト（Cold Draft）は冬季に断熱性能の低い窓ガラス・外壁面が冷却され、その表面に接した暖かい室内空気が冷やされて下降する冷気流。足元が特に寒く感じられる不快な現象を引き起こし、エネルギーロスにもなる。対策としてLow-Eトリプルガラス等の高断熱窓・窓下への暖房器具（パネルヒーター等）の設置・足元暖房（床暖房等）が有効。\n\nB：ヒートアイランド現象は都市部の気温が郊外より高くなる現象（アスファルト・コンクリートの熱吸収・緑地減少・廃熱増加等が原因）で、建物内部の断熱材の蓄熱とは全く異なる現象。記述は誤り。\nC：日射遮蔽効果は内付けよりも外付け（庇・外付けブラインド・ルーバー等）の方が大幅に優れる。室内のカーテン・内付けブラインドは日射が室内に入った後に遮るため、既に室内に熱が侵入した状態での遮蔽になる。外付けでは日射を室外で遮断できるため効果が高い。\nD：輻射冷暖房（放射冷暖房）は壁面・天井・床に冷温水を循環させて表面温度を変化させ、その面からの輻射（放射）熱で室内を快適にする方式。空気を直接加熱・冷却するのではなく、輻射熱を利用することが本質。「ファンのみ・輻射を利用しない」は正反対の記述。\n\n【頻出】コールドドラフトの発生原因と対策・日射遮蔽の内付けと外付けの効果の差・輻射冷暖房の原理は温熱環境問題の頻出テーマ。\n【混同注意】対流（空気の動き）と輻射（電磁波による熱移動）は熱の伝わり方が全く異なる。輻射冷暖房は空気でなく放射熱で快適性を実現する方式であることを確実に理解すること。"

