"排水管の勾配は水の自然流下を確保するために重要で、一般に横引き排水管は1/50〜1/100程度の勾配が適正とされ、勾配が急すぎると水だけが先に流れてしまい汚物が管内に残る現象が起きやすくなる",

"通気管はトラップの封水保護・排水の流れを円滑にする役割に加え、逆流した汚水をトラップから室内に押し出す排出機能を持つとされる",

