"explanation": "建築工事費の費用構成は、直接工事費（仮設工事・土工事・躯体工事・仕上げ工事・設備工事等の実際の施工費）＋間接工事費（仮設費・現場管理費・安全管理費等）＝工事原価、これに一般管理費（本社経費・利益・営業費等）を加えたものが請負工事費（施主が支払う工事費）となる。このコスト構成の理解はコーディネーターが施主のコスト管理を支援する上で基礎知識。\n\nB：設計監理費は施主が設計事務所・建築士に支払う設計・工事監理のための報酬（設計料）。「施工会社が施工品質管理のために支払う費用・施主負担不要」は誤り。施主が設計者に直接支払う費用。\nC：数量×単価で工事費を積算する方法は「積算（数量積算・実行予算）」と呼ばれ、「価格比較法」は一般的な呼称ではない。また法律上の外部審査義務も一般的な民間工事には存在しない。\nD：インテリア工事費（内装仕上げ工事・家具・照明・カーテン等）は躯体工事とは明確に区分されて見積計上されることが一般的。「躯体工事費に含まれる・独立計上されない」は誤り。\n\n【頻出】建築工事費の費用構成（直接工事費・間接工事費・一般管理費）と積算の基本知識・設計監理費の位置づけはコーディネート業務の財務知識として頻出。\n【混同注意】直接工事費（実際の工事のコスト）・間接工事費（現場運営コスト）・一般管理費（会社経費・利益）の3層構造を整理すること。施主が支払う「請負工事費」はこの合計であることを理解する。"

