"explanation": "ホームセキュリティシステムは防犯センサー（マグネットセンサー・赤外線センサー等）・火災・ガス漏れ・緊急ボタン等を組み合わせたシステム。専門のセキュリティ会社（セコム・ALSOK等）と警備契約を結ぶことで、異常検知時に警備会社のセンターに信号が送られ、警備員の現場駆けつけ・警察・消防への連絡等の対応が受けられる。住宅の安全性向上に有効なサービス。\n\nB：公共の場・自己所有の建物の玄関・駐車場等への防犯カメラの設置は、撮影目的・範囲・管理方法を適切に設定することで法的に認められる。「すべての場合で禁止・違法」は誤り。ただしプライバシーへの配慮・個人情報保護法への対応は必要。\nC：二重鍵（ダブルロック）の採用は防犯性向上に有効だが、建築基準法による義務付け規定は存在しない。任意の防犯対策として推奨される。\nD：防犯ガラス（合わせガラス）は侵入に時間・手間がかかるようにして犯罪機会を減らす製品だが、「いかなる工具でも割れない・侵入完全防止」という絶対的な機能はない。十分な時間と工具があれば破壊できる可能性があり、「完全防止」の保証はない。\n\n【頻出】ホームセキュリティシステムの構成（センサー・警備会社連携）・防犯カメラの法的位置づけ（適切な設置は合法）・防犯ガラスの効果と限界は住宅防犯計画の頻出テーマ。\n【混同注意】防犯設備は「犯罪を不可能にする」のではなく「犯罪の機会を減らし・リスクを高める（CPTEDの原則）」ことを目的とする。「完全な防犯」は存在しないが対策の積み重ねで抑止効果を高められる。"

