"explanation": "住宅性能表示制度（住宅品質確保促進法・品確法第3〜6章）は任意の制度で、住宅の性能を設計段階（設計住宅性能評価）と施工完了後（建設住宅性能評価）の二段階で指定住宅性能評価機関（第三者機関）が評価・認定する。評価結果は構造安定・火災時安全・劣化対策・維持管理更新・温熱環境・空気環境・音環境・高齢者等配慮・防犯等の複数項目で等級表示される。\n\nB：住宅性能表示は義務ではなく任意の制度。取得しなくても建築確認申請は可能であり、「取得なしで確認申請不可」は誤り。\nC：住宅性能表示の評価項目は構造安定（耐震等級等）・火災時安全・劣化対策・維持管理・温熱環境（断熱等級）・空気環境・光・視環境・音環境・高齢者等配慮・防犯の計10〜11分野にわたる総合的な評価。「耐震性のみ」は誤り。\nD：住宅性能評価書は取得時点の設計・施工の確認であり、評価後の欠陥についての無限定な補修責任を評価機関が負うわけではない。品質保証は法律上の瑕疵担保責任・品確法の瑕疵担保等によるもので、評価機関の永久保証という制度ではない。\n\n【頻出】住宅性能表示制度の任意性・二段階評価（設計評価・建設評価）・多分野の評価項目（構造・断熱・バリアフリー・防犯等）は品確法問題の頻出テーマ。\n【混同注意】住宅性能表示（任意・第三者評価・等級表示）と長期優良住宅認定（行政認定・基準適合確認）・瑕疵担保責任（法的義務・10年間）は異なる制度。それぞれの目的・性格の違いを整理すること。"

