"ホームシアターの音響設計において、壁面全体を鏡面仕上げ・ガラス張りにすることで音の反射が均一化され、最高の音響環境が実現できるとされる",

"プロジェクター使用のホームシアターでは室内を明るくするほど映像の発色・コントラストが向上するため、大きな窓と強力な照明の設置が推奨されるとされる",

"サラウンドシステムの推奨スピーカー配置において、すべてのスピーカーを視聴者の正面に集中配置することで没入感が最大化されるとされる"

