"explanation": "熱帯・亜熱帯気候（高温多湿）での住宅設計では過熱・湿気への対応が最重要。高床式（地面からの湿気・熱を遮断）・通風促進（クロスベンチレーション・高窓・縁側・雨端）・日射遮蔽（深い庇・ルーバー・緑陰）・軽量素材による蓄熱抑制がその特徴的手法。沖縄の伝統的建築（赤瓦屋根・琉球石灰岩の石垣・雨端〔あまはじ：深い軒下空間〕）はこれらの要素を自然発生的に備えた気候適応建築として知られる。\n\nB：寒冷気候（北海道・東北等）の建物設計では断熱性能の最大化・気密化・計画換気による熱損失の最小化が最優先事項。「通風最大化・断熱材排除」は全く逆の設計方針で誤り。\nC：乾燥気候での建物設計では蒸発冷却・夜間の通風による放熱・中庭（パティオ）等が重要な手法であり、「開口部を完全封鎖・外気遮断」は逆効果で誤り。\nD：日本の太平洋側・瀬戸内・日本海側・北海道・沖縄等では気候が大きく異なり、降雪・結露・日射・風等の地域特性に応じた設計の差異化が必要不可欠。「同一基準・差異化不要」は誤り。\n\n【頻出】日本各地の気候特性と伝統的住宅形式（沖縄の赤瓦・雨端・北海道の高断熱・合掌造りの豪雪対策等）の対応関係は気候適応設計問題の頻出テーマ。\n【混同注意】気候適応設計は「温暖地→開放的・通風重視」「寒冷地→閉鎖的・断熱重視」という大きな方向性の違いがある。どちらの気候での設計問題かを確認してから解答すること。"

