"explanation": "安藤忠雄（1941年〜）は大阪府出身の建築家で、正規の建築教育を受けず独学・ボクシング・旅等から建築を学んだ経歴を持つ。打放しコンクリートの質感・幾何学的な構成・光の取り入れ方が特徴的な「住吉の長屋」（1976年）・「光の教会」（1989年）・「直島文化村（地中美術館）」等の代表作で国際的に高い評価を受けたプリツカー賞受賞建築家。\n\nB：丹下健三（1913〜2005年）は日本人の建築家で、日本のモダニズム建築を代表する人物。国立代々木競技場（1964年東京オリンピック）等の代表作を持つ。「フランス人・招聘・帰化」はすべて誤り。\nC：隈研吾は1954年生まれの現代日本の建築家で、木・石・竹・紙等の素材を現代建築に取り込む「素材感の建築」で知られる。1920年代の人物ではなく、コンクリート排除・超高層木造建築という記述も現実の設計とは異なる誇張された誤りの説明。\nD：吉村順三（1908〜1997年）は日本の建築家・インテリアデザイナーで、自然と共存した住宅設計・繊細な木工の美を追求した。バウハウス卒業生ではなく、アントニン・レーモンドに師事した日本人建築家。\n\n【頻出】日本の代表的建築家（安藤忠雄・丹下健三・隈研吾・黒川紀章・磯崎新等）の特徴的なスタイル・代表作・受賞歴は近代日本建築史の頻出テーマ。\n【混同注意】安藤忠雄（独学・コンクリート・大阪）と隈研吾（木・石・竹・現代）・丹下健三（戦後モダニズム・コンクリート×日本的表現）は同じ「日本の著名建築家」でも方向性が全く異なる。"

