"explanation": "色の恒常性（カラーコンスタンシー）は人間の視覚・脳の知覚補正機能で、照明色が変化してもある程度まで物体の「本来の色」として知覚し続ける現象。ただし補正は完全ではなく、電球色（暖色）下では素材が暖かみを帯びて見え、昼光色（寒色）下では涼しげに見える等、照明条件によって実際の色の印象は変化する。インテリアの素材・カラー選定では実際の設置環境に近い照明条件でのサンプル確認が必要。\n\nB：色の恒常性は「ある程度まで補正する傾向」であり、完全な補正ではない。照明色温度の違いによって素材の見え方は実際に変化するため、現地確認は重要。「変化なし・確認不要」は誤り。\nC：色の恒常性は照度変化だけでなく、光の色（色温度・分光分布）の変化に対しても働く現象。「照度のみ・色温度変化で見え方変わらない」は誤り。\nD：電球色と昼光色では素材の色の見え方が実際に異なり、色の恒常性による補正後も明らかな違いが生じる。「完全に同一に見えることが保証」は誤り。\n\n【頻出】色の恒常性の概念・照明条件による素材の見え方の変化・現地確認（実際の光源下でのサンプル確認）の重要性は色彩・照明計画の実践的頻出テーマ。\n【混同注意】色の恒常性は「完全補正」ではなく「傾向的補正」。どのような照明でも同じに見えるという誤解が最も多い。"

