"explanation": "建物のLCA（Life Cycle Assessment）は建材の原料採取・製造・輸送・施工・居住中のエネルギー消費・メンテナンス・解体・廃棄・リサイクルまでの全ライフサイクルにわたる環境負荷（CO₂排出量・エネルギー消費量・資源消費等）を定量的に評価する手法。ISO 14040/14044に規定される国際標準的な環境評価手法で、カーボンニュートラル・脱炭素建築の評価に活用される。\n\nB：LCAの特徴はライフサイクル「全体」を評価対象とすることにあり、使用段階のみの評価はオペレーショナルエネルギー評価（省エネ評価）に近い概念。製造・施工・解体廃棄の「エンボディドカーボン」もLCAの重要評価対象。\nC：LCC（ライフサイクルコスト）は建物の生涯にわたる「金銭的コスト」（建設費＋維持管理費＋解体費）を評価する手法。LCA（ライフサイクルアセスメント）は「環境負荷」を評価する手法。同義語ではなく目的・評価対象が異なる。\nD：LCAとBELSは異なる評価制度で、LCAで高評価でも必ずしもBELS5星と連動しない。BELSは主に運用段階の省エネ性能を評価するもので、LCAのライフサイクル全体の評価とは異なる。\n\n【頻出】LCAの概念（全ライフサイクル・環境負荷評価）とLCC（金銭的コスト評価）の違い・エンボディドカーボンの概念は近年の脱炭素建築テーマとして出題増加。\n【混同注意】LCA（環境負荷・CO₂）とLCC（金銭的コスト）は評価対象が根本的に異なる。「ライフサイクル」という共通語句を持つが全く別の評価手法。"

