"explanation": "リビング・ダイニングへのスタディコーナー設置は「リビング学習」として近年の住宅計画で注目されるアプローチ。親が料理・家事をしながら子どもの学習を見守れる利点があり、子どもの学習意欲向上にも貢献するとする研究もある。ダイニングテーブルとは別に専用デスク・棚を確保することで書籍・文具の収納と集中できる学習環境を提供できる。\n\nB：タスクライト（手元照明）はデスク作業時の手元照度を確保し、目の疲労を軽減するために推奨される照明。「視力に悪影響・設置すべきでない」は全くの逆で誤り。手元が暗すぎる方が眼精疲労を招く。\nC：高さ調整機能付きデスク・椅子は成長に合わせて最適な高さに調整できるため、成長期の子ども向けに特に推奨される製品。「高さ調整は不安定・使用避けるべき」は誤り。\nD：廊下への家具設置について一律禁止の建築基準法規定は存在しない。ただし避難経路として必要な有効幅（用途・規模による）を確保することは必要で、全幅を塞ぐような設置は問題となる場合がある。「法律上一切認められない」は過度な断定で誤り。\n\n【頻出】リビング学習（スタディコーナー）の設計メリット・タスクライトの推奨（手元照度確保）・成長に合わせた高さ調整机の有用性はワークスペース・子育て住宅計画の頻出テーマ。\n【混同注意】「目のために明るくする必要がある」というタスクライトの目的と「高照度は目に悪い」という誤解を混同しないこと。適切な手元照度の確保（300〜750lx）が重要。"

