"explanation": "建築基準法では増築時に既存部分を含む建物全体を現行法規に適合させる必要があるかどうかの判断が必要。既存不適格建築物への増築・増築規模・用途変更等によっては、既存部分を含めた遡及適用（現行基準への適合）が求められる場合がある（建築基準法第3条・令第137条の2等）。ただし「既存不適格緩和規定」により一定条件下での増築が認められる場合もある。\n\nB：延べ床面積10㎡以下の増築が防火・準防火地域以外で確認申請不要となることは正しい。しかし「建築基準法上の規制が全く適用されない」は誤りで、確認申請が不要でも建築基準法の実体規定（構造・防火等）は遵守しなければならない。\nC：既存不適格建築物への増改築は禁止されておらず、規模・内容によっては一定の条件下で認められる。「全て解体・新築が必須」は誤り。既存不適格緩和規定が設けられている。\nD：増築工事の発注方式について一括発注を義務付けた建築基準法の規定は存在しない。分離発注・施主施工（自ら工事する場合：電気工事士等の資格が必要な工事を除く）も認められている。\n\n【頻出】既存不適格建築物の概念・増築時の遡及適用の問題・10㎡以下増築の確認申請不要（防火地域外）は建築法規問題の頻出テーマ。\n【混同注意】「確認申請不要＝建築基準法の規制が全く適用されない」という誤解が最も多い。確認申請が不要な場合でも、構造・防火等の実体規定の遵守は義務。"

