"explanation": "インテリアコーディネーターの報酬形態には複数の方式が実際に存在する。パーセンテージフィー（工事費・購入金額の5〜15%程度）・タイムチャージ（時間単価×時間数）・定額プロジェクトフィー・コンサルティングフィー（相談単位の時間制）・コミッション（メーカー・卸からの手数料）等があり、プロジェクトの規模・業務内容・市場慣行・クライアントとの合意に基づいて選択される。\n\nB：インテリアコーディネーターは民間資格であり、建築士法に基づく国土交通省の報酬基準規定は存在しない。「法定報酬額」に従う義務もなく、コーディネーターと依頼者間の自由な合意で報酬を決定できる。\nC：コンサルティングのみ（施工なし）の有償サービスを禁じた法律・業界規制は存在しない。施工を伴わない有償コンサルティング（時間制アドバイス等）は欧米でも一般的に行われており、日本でも認められているビジネスモデル。\nD：インテリアコーディネーターは施主から直接報酬を受け取ることができる（直接クライアントフィー方式）。施工会社からのキックバックのみという説明は誤りであり、利益相反を避けるためにも施主からの直接フィーが倫理的に望ましいとされる場合が多い。\n\n【頻出】インテリアコーディネーターの報酬形態（パーセンテージ・タイムチャージ・定額・コンサルティング）の種類と選択基準・施主からの直接フィーの倫理的意義はコーディネート業務論の頻出テーマ。\n【混同注意】キックバック（施工会社等からの手数料）と施主直接フィーの違い：キックバックのみでは利益相反（施主の利益より自己利益優先）のリスクがある。透明性の確保がプロとしての重要な倫理的原則。"

