"explanation": "カーテンのヒダ倍率はカーテン開口幅に対して使用する生地量の比率。2倍ヒダは完成カーテン幅の2倍の生地を使用し、豊かなドレープ（ひだ）が形成される。1.5倍ヒダは生地使用量が少なくなりすっきりとした印象・コスト低減が利点だが、2倍ヒダより立体的なひだの膨らみが少なくなる傾向がある。高級感・重厚感を重視するリビングには2倍ヒダが適するとされることが多い。\n\nB：床クリアランス（床とカーテン裾の隙間：10〜15mm程度）は掃除のしやすさ・カーテンの傷みを防ぐための実用的な設定で、現代のインテリアでも一般的に採用される。「見た目が悪い・床面に必ずぴったり」という断定は誤り。なおホテル・高級インテリアではあえて床にたらすプリーツの演出も行われる。\nC：防炎カーテンは不燃性（燃えない）ではなく防炎性（燃え広がりにくく自己消火性がある）素材・加工の製品。炎を取り除けば自消するが「不燃性」とは異なる。防炎加工は後加工でも可能で、可燃性素材に防炎剤を処理した製品も存在する。\nD：ダブルレールはドレープ（厚地）とレースカーテンを重ねて吊るすための設備で、2枚は目的・機能が異なる異なる生地を組み合わせることが一般的。「同一生地義務」は誤り。\n\n【頻出】カーテンのヒダ倍率（2倍ヒダ・1.5倍ヒダの違い）・防炎カーテンの性質（防炎≠不燃）・ダブルレールの用途はカーテン選定問題の頻出テーマ。\n【混同注意】防炎性（自消・燃え広がらない）と不燃性（着火しない）は全く異なる概念。カーテンの防炎製品は「燃えにくい・自消」であり「燃えない（不燃）」ではない。"

