"explanation": "インテリアコーディネーターの職業的本質は「施主の生活・夢を実現する専門的パートナー」としての役割にある。深いヒアリング・共感・施主の価値観の理解に基づき、色彩・素材・照明・家具・空間計画・建築法規・設備等の幅広い専門知識を統合して最適な提案を行う。同時に倫理的姿勢（透明性・誠実さ・利益相反の回避）・継続的な専門能力の向上・完成後のアフターフォローへの誠実な対応が長期的な信頼関係と職業的評価の基盤となる。\n\nB：コーディネーターの美的センスは重要な専門能力のひとつだが、「コーディネーター自身の美を最大発揮・施主の意向は最小」は職業倫理の根本的な逸脱。施主の生活空間を扱う職業では施主中心主義が絶対的な基本原則。\nC：引渡し後のフォローアップ・アフターサービスへの誠実な対応は施主との信頼関係の維持・職業的評判の向上・次の仕事への繋がりにとって重要な業務の一部。「断ることが推奨される業務範囲外」は誤り。\nD：施主からの満足の評価と資格の剥奪を直接結びつけた制度は存在しない。資格の更新は所定の継続教育・研修の受講等の要件によるもので、個々のプロジェクト評価による即時剥奪制度はない。\n\n【頻出】インテリアコーディネーターの職業倫理・施主中心主義・継続的専門能力向上・アフターフォローの重要性はコーディネート業務の総合問題として試験の最後に問われる総括的テーマ。\n【混同注意】コーディネーターの「専門性の発揮」と「施主の意向の尊重」は対立するものではなく、専門的知識を施主の夢・生活実現のために使うことが本来の姿。どちらか一方に偏ることが問題。"

